// fir Optimizer — P3.3 Constant Folding
// 컴파일 타임에 평가 가능한 표현식을 상수로 대체
//
// 패턴:
//   %r = add i64 3, 4        → %r = 7   (상수 전파)
//   %r = mul i64 0, %x       → %r = 0   (zero rule)
//   %r = mul i64 1, %x       → %r = %x  (identity)
//   %r = sub i64 %x, 0       → %r = %x
//   %r = icmp eq %x, %x      → %r = 1   (same operand)
//   %r = brcond true, L1, L2 → br L1    (constant branch)
package opt

import (
	"math"
	"fir/src/ir"
)

// ----------------------------------------------------------------
// ConstFoldPass
// ----------------------------------------------------------------

type ConstFoldPass struct{}

func (p *ConstFoldPass) Name() string { return "constfold" }

func (p *ConstFoldPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		foldFunc(fn)
	}
	return mod
}

// ----------------------------------------------------------------
// 함수 단위 폴딩 (반복 수렴)
// ----------------------------------------------------------------

func foldFunc(fn *ir.Function) {
	// 수렴할 때까지 반복 (한 번에 다 안 될 수 있음)
	for {
		changed := false
		for _, b := range fn.Blocks {
			if foldBlock(b) { changed = true }
		}
		if !changed { break }
	}
}

// ----------------------------------------------------------------
// 블록 단위 폴딩
// ----------------------------------------------------------------

func foldBlock(b *ir.Block) bool {
	changed := false
	newInsts := make([]*ir.Inst, 0, len(b.Insts))

	for _, inst := range b.Insts {
		folded, replacement := tryFold(inst)
		if folded {
			// replacement가 nil이면 instruction 자체 제거
			// (dead branch 제거 등)
			if replacement != nil {
				newInsts = append(newInsts, replacement)
			}
			changed = true
		} else {
			newInsts = append(newInsts, inst)
		}
	}

	b.Insts = newInsts
	return changed
}

// ----------------------------------------------------------------
// 개별 instruction 폴딩 시도
// ----------------------------------------------------------------

// tryFold: (folded bool, replacement *ir.Inst)
// folded=true, replacement=nil  → 제거
// folded=true, replacement=inst → 교체

// fir Phase 3 — Optimizer 검증
// 원칙: interp(before) == interp(after), 그리고 코드가 줄어야 함
package main

import (
	"fmt"
	"fir/src/interp"
	"fir/src/ir"
	"fir/src/irgen"
	"fir/src/opt"
)

var optPassed, optFailed int

// ----------------------------------------------------------------
// 헬퍼
// ----------------------------------------------------------------

func countInsts(mod *ir.Module) int {
	n := 0
	for _, fn := range mod.Functions {
		for _, b := range fn.Blocks {
			n += len(b.Insts)
		}
	}
	return n
}

// 최적화 전후 interp 결과 동일, 명령 수 감소/동일 검증
func assertOpt(label string, mod *ir.Module, fnName string,
	args []interp.RVal, expected int64) {
	before, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | before interp: %v\n", label, err)
		optFailed++
		return
	}
	nBefore := countInsts(mod)

	// 최적화 실행
	pm := opt.Standard()
	modOpt := pm.Run(mod)

	after, err := interp.ExecModule(modOpt, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | after interp: %v\n", label, err)
		optFailed++
		return
	}
	nAfter := countInsts(modOpt)

	if before.AsInt() != expected {
		fmt.Printf("[FAIL] %s | before=%d expected=%d\n", label, before.AsInt(), expected)
		optFailed++
		return
	}
	if after.AsInt() != expected {
		fmt.Printf("[FAIL] %s | after=%d expected=%d (semantics broken!)\n",
			label, after.AsInt(), expected)
		optFailed++
		return
	}

	fmt.Printf("[PASS] %s | result=%d insts: %d→%d (-%d)\n",
		label, expected, nBefore, nAfter, nBefore-nAfter)
	optPassed++
}

// FL 소스 경유 최적화 검증
func assertOptFL(label, src, fnName string, args []interp.RVal, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | irgen: %v\n", label, err)
		optFailed++
		return
	}
	assertOpt(label, mod, fnName, args, expected)
}

// ----------------------------------------------------------------

