   230→// ----------------------------------------------------------------
   231→// FCmp 폴딩
   232→// ----------------------------------------------------------------
   233→
   234→func foldFCmp(inst *ir.Inst) (bool, *ir.Inst) {
   235→	lhs, rhs := inst.LHS, inst.RHS
   236→	if isConstFloat(lhs) && isConstFloat(rhs) {
   237→		var cmp bool
   238→		l, r := lhs.FVal, rhs.FVal
   239→		switch inst.Pred {
   240→		case "oeq": cmp = l == r
   241→		case "one": cmp = l != r
   242→		case "olt": cmp = l < r
   243→		case "ole": cmp = l <= r
   244→		case "ogt": cmp = l > r
   245→		case "oge": cmp = l >= r
   246→		}
   247→		v := int64(0)
   248→		if cmp { v = 1 }
   249→		return true, makeConst(inst.Result, ir.Bool(), v, 0, false)
   250→	}
   251→	return false, nil
   252→}
   253→
   254→// ----------------------------------------------------------------
   255→// BrCond 폴딩 → 무조건 Br
   256→// ----------------------------------------------------------------
   257→
   258→func foldBrCond(inst *ir.Inst) (bool, *ir.Inst) {
   259→	cond := inst.Cond
   260→	if cond.Kind == ir.ValConstBool {
   261→		if cond.BVal {
   262→			return true, ir.NewBr(inst.TrueLabel)
   263→		}
   264→		return true, ir.NewBr(inst.FalseLabel)
   265→	}
   266→	if cond.Kind == ir.ValConstInt {
   267→		if cond.IVal != 0 {
   268→			return true, ir.NewBr(inst.TrueLabel)
   269→		}
   270→		return true, ir.NewBr(inst.FalseLabel)
   271→	}
   272→	return false, nil
   273→}
   274→
   275→// ----------------------------------------------------------------
   276→// Cast 폴딩
   277→// ----------------------------------------------------------------
   278→
   279→func foldCast(inst *ir.Inst) (bool, *ir.Inst) {
   280→	v := inst.Operand
   281→	if !isConstInt(v) && !isConstFloat(v) { return false, nil }
   282→
   283→	switch inst.Op {
   284→	case "trunc":
   285→		if isConstInt(v) {
   286→			iv := v.IVal
   287→			switch inst.ToType.Name {
   288→			case "i8",  "u8":  iv &= 0xFF
   289→			case "i16", "u16": iv &= 0xFFFF
   290→			case "i32", "u32": iv &= 0xFFFFFFFF
   291→			}
   292→			return true, makeConst(inst.Result, inst.ToType, iv, 0, false)
   293→		}
   294→	case "zext", "sext":
   295→		if isConstInt(v) {
   296→			return true, makeConst(inst.Result, inst.ToType, v.IVal, 0, false)
   297→		}
   298→	case "sitofp":
   299→		if isConstInt(v) {
   300→			return true, makeConst(inst.Result, inst.ToType, 0, float64(v.IVal), true)
   301→		}
   302→	case "fptosi":
   303→		if isConstFloat(v) {
   304→			return true, makeConst(inst.Result, inst.ToType, int64(v.FVal), 0, false)
   305→		}
   306→	case "bitcast", "ptrtoint", "inttoptr":
   307→		if isConstInt(v) {
   308→			return true, makeConst(inst.Result, inst.ToType, v.IVal, 0, false)
   309→		}
   310→	}
   311→	return false, nil
   312→}
   313→
   314→// ----------------------------------------------------------------
   315→// 헬퍼
   316→// ----------------------------------------------------------------
   317→
   318→func isConstInt(v *ir.Value) bool {
   319→	return v != nil && v.Kind == ir.ValConstInt
   320→}
   321→
   322→func isConstFloat(v *ir.Value) bool {
   323→	return v != nil && v.Kind == ir.ValConstFloat
   324→}
   325→
   326→func isZeroInt(v *ir.Value) bool {
   327→	return isConstInt(v) && v.IVal == 0
   328→}
   329→
   330→func isOneInt(v *ir.Value) bool {
   331→	return isConstInt(v) && v.IVal == 1
   332→}
   333→
   334→func sameReg(a, b *ir.Value) bool {
   335→	return a != nil && b != nil &&
   336→		a.Kind == ir.ValReg && b.Kind == ir.ValReg &&
   337→		a.Name == b.Name
   338→}
   339→
   340→// makeConst: %result = const
   341→func makeConst(result string, t *ir.Type, ival int64, fval float64, isF bool) *ir.Inst {
   342→	var val *ir.Value
   343→	if isF {
   344→		val = ir.ConstFloat(fval, t)
   345→	} else {
   346→		val = ir.ConstInt(ival, t)
   347→	}
   348→	// binop add 0,0 형태로 상수를 "move"처럼 표현
   349→	// 실제로는 ret/store 등이 직접 상수 Value를 참조하도록
   350→	// move instruction: %r = add T val, 0  → 너무 번거로움
   351→	// 대신: %r = add T 0, 0 처럼 쓰면 codegen이 상수를 직접 emit
   352→	// 가장 깔끔한 방법: InstBinop add 0+0을 쓰지 말고
   353→	// use-site에서 Value를 상수로 치환하는 방식
   354→	// 여기서는 "move" 패턴: add %r, val, 0
   355→	if isF {
   356→		return ir.NewBinop("fadd", result, t, val, ir.ConstFloat(0, t))
   357→	}
   358→	return ir.NewBinop("add", result, t, val, ir.ConstInt(0, t))
   359→}
   360→
   361→// makeMove: %result = %src (copy)
   362→func makeMove(result string, t *ir.Type, src *ir.Value) *ir.Inst {
