// ----------------------------------------------------------------
// FCmp 폴딩
// ----------------------------------------------------------------

func foldFCmp(inst *ir.Inst) (bool, *ir.Inst) {
	lhs, rhs := inst.LHS, inst.RHS
	if isConstFloat(lhs) && isConstFloat(rhs) {
		var cmp bool
		l, r := lhs.FVal, rhs.FVal
		switch inst.Pred {
		case "oeq": cmp = l == r
		case "one": cmp = l != r
		case "olt": cmp = l < r
		case "ole": cmp = l <= r
		case "ogt": cmp = l > r
		case "oge": cmp = l >= r
		}
		v := int64(0)
		if cmp { v = 1 }
		return true, makeConst(inst.Result, ir.Bool(), v, 0, false)
	}
	return false, nil
}

// ----------------------------------------------------------------
// BrCond 폴딩 → 무조건 Br
// ----------------------------------------------------------------

func foldBrCond(inst *ir.Inst) (bool, *ir.Inst) {
	cond := inst.Cond
	if cond.Kind == ir.ValConstBool {
		if cond.BVal {
			return true, ir.NewBr(inst.TrueLabel)
		}
		return true, ir.NewBr(inst.FalseLabel)
	}
	if cond.Kind == ir.ValConstInt {
		if cond.IVal != 0 {
			return true, ir.NewBr(inst.TrueLabel)
		}
		return true, ir.NewBr(inst.FalseLabel)
	}
	return false, nil
}

// ----------------------------------------------------------------
// Cast 폴딩
// ----------------------------------------------------------------

func foldCast(inst *ir.Inst) (bool, *ir.Inst) {
	v := inst.Operand
	if !isConstInt(v) && !isConstFloat(v) { return false, nil }

	switch inst.Op {
	case "trunc":
		if isConstInt(v) {
			iv := v.IVal
			switch inst.ToType.Name {
			case "i8",  "u8":  iv &= 0xFF
			case "i16", "u16": iv &= 0xFFFF
			case "i32", "u32": iv &= 0xFFFFFFFF
			}
			return true, makeConst(inst.Result, inst.ToType, iv, 0, false)
		}
	case "zext", "sext":
		if isConstInt(v) {
			return true, makeConst(inst.Result, inst.ToType, v.IVal, 0, false)
		}
	case "sitofp":
		if isConstInt(v) {
			return true, makeConst(inst.Result, inst.ToType, 0, float64(v.IVal), true)
		}
	case "fptosi":
		if isConstFloat(v) {
			return true, makeConst(inst.Result, inst.ToType, int64(v.FVal), 0, false)
		}
	case "bitcast", "ptrtoint", "inttoptr":
		if isConstInt(v) {
			return true, makeConst(inst.Result, inst.ToType, v.IVal, 0, false)
		}
	}
	return false, nil
}

// ----------------------------------------------------------------
// 헬퍼
// ----------------------------------------------------------------

func isConstInt(v *ir.Value) bool {
	return v != nil && v.Kind == ir.ValConstInt
}

func isConstFloat(v *ir.Value) bool {
	return v != nil && v.Kind == ir.ValConstFloat
}

func isZeroInt(v *ir.Value) bool {
	return isConstInt(v) && v.IVal == 0
}

func isOneInt(v *ir.Value) bool {
	return isConstInt(v) && v.IVal == 1
}

func sameReg(a, b *ir.Value) bool {
	return a != nil && b != nil &&
		a.Kind == ir.ValReg && b.Kind == ir.ValReg &&
		a.Name == b.Name
}

// makeConst: %result = const
func makeConst(result string, t *ir.Type, ival int64, fval float64, isF bool) *ir.Inst {
	var val *ir.Value
	if isF {
		val = ir.ConstFloat(fval, t)
	} else {
		val = ir.ConstInt(ival, t)
	}
	// binop add 0,0 형태로 상수를 "move"처럼 표현
	// 실제로는 ret/store 등이 직접 상수 Value를 참조하도록
	// move instruction: %r = add T val, 0  → 너무 번거로움
	// 대신: %r = add T 0, 0 처럼 쓰면 codegen이 상수를 직접 emit
	// 가장 깔끔한 방법: InstBinop add 0+0을 쓰지 말고
	// use-site에서 Value를 상수로 치환하는 방식
	// 여기서는 "move" 패턴: add %r, val, 0
	if isF {
		return ir.NewBinop("fadd", result, t, val, ir.ConstFloat(0, t))
	}
	return ir.NewBinop("add", result, t, val, ir.ConstInt(0, t))
}

// makeMove: %result = %src (copy)
func makeMove(result string, t *ir.Type, src *ir.Value) *ir.Inst {
	if src.Type != nil && (src.Type.Kind == ir.TyF32 || src.Type.Kind == ir.TyF64) {
		return ir.NewBinop("fadd", result, t, src, ir.ConstFloat(0, t))
	}
	return ir.NewBinop("add", result, t, src, ir.ConstInt(0, t))
}

// Free IR 1.0 — IR Nodes
package ir

import (
	"fmt"
	"strings"
)

// ----------------------------------------------------------------
// Value (SSA)
// ----------------------------------------------------------------

type ValueKind int

const (
	ValReg ValueKind = iota
	ValConstInt
	ValConstFloat
	ValConstBool
	ValConstNull
	ValGlobalRef
)

type Value struct {
	Kind  ValueKind
	Type  *Type
	Name  string  // reg name or global name
	IVal  int64
	FVal  float64
	BVal  bool
}

func Reg(name string, t *Type) *Value {
	return &Value{Kind: ValReg, Name: name, Type: t}
}

func ConstInt(v int64, t *Type) *Value {
	return &Value{Kind: ValConstInt, IVal: v, Type: t}
}

func ConstFloat(v float64, t *Type) *Value {
	return &Value{Kind: ValConstFloat, FVal: v, Type: t}
}

func ConstBool(v bool) *Value {
	b := 0
	if v { b = 1 }
	return &Value{Kind: ValConstBool, BVal: v, IVal: int64(b), Type: Bool()}
}

func ConstNull(t *Type) *Value {
	return &Value{Kind: ValConstNull, Type: t}
}

func GlobalRef(name string, t *Type) *Value {
	return &Value{Kind: ValGlobalRef, Name: name, Type: t}
}

func (v *Value) String() string {
	switch v.Kind {
	case ValReg:
		return "%" + v.Name
	case ValConstInt:
		return fmt.Sprintf("%d", v.IVal)
	case ValConstFloat:
		return fmt.Sprintf("%g", v.FVal)
	case ValConstBool:
		if v.BVal { return "true" }
		return "false"
	case ValConstNull:
		return "null"
	case ValGlobalRef:
		return "@" + v.Name
	}
	return "?"
}

// ----------------------------------------------------------------
// Instruction
// ----------------------------------------------------------------

type InstKind int

const (
	InstBinop InstKind = iota
	InstNeg
	InstICmp
	InstFCmp
	InstAlloca
	InstLoad
	InstStore
	InstGEP
	InstCast
	InstCall
	InstBr
	InstBrCond
	InstRet
	InstRetVoid
	InstPhi
)

