// fir Optimizer — P3.3 Constant Folding
// 컴파일 타임에 평가 가능한 표현식을 상수로 대체
//
// 패턴:
//   %r = add i64 3, 4        → %r = 7   (상수 전파)
//   %r = mul i64 0, %x       → %r = 0   (zero rule)
//   %r = mul i64 1, %x       → %r = %x  (identity)
//   %r = sub i64 %x, 0       → %r = %x
//   %r = icmp eq %x, %x      → %r = 1   (same operand)
//   %r = brcond true, L1, L2 → br L1    (constant branch)
package opt

import (
	"math"
	"fir/src/ir"
)

// ----------------------------------------------------------------
// ConstFoldPass
// ----------------------------------------------------------------

type ConstFoldPass struct{}

func (p *ConstFoldPass) Name() string { return "constfold" }

func (p *ConstFoldPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		foldFunc(fn)
	}
	return mod
}

// ----------------------------------------------------------------
// 함수 단위 폴딩 (반복 수렴)
// ----------------------------------------------------------------

func foldFunc(fn *ir.Function) {
	// 수렴할 때까지 반복 (한 번에 다 안 될 수 있음)
	for {
		changed := false
		for _, b := range fn.Blocks {
			if foldBlock(b) { changed = true }
		}
		if !changed { break }
	}
}

// ----------------------------------------------------------------
// 블록 단위 폴딩
// ----------------------------------------------------------------

func foldBlock(b *ir.Block) bool {
	changed := false
	newInsts := make([]*ir.Inst, 0, len(b.Insts))

	for _, inst := range b.Insts {
		folded, replacement := tryFold(inst)
		if folded {
			// replacement가 nil이면 instruction 자체 제거
			// (dead branch 제거 등)
			if replacement != nil {
				newInsts = append(newInsts, replacement)
			}
			changed = true
		} else {
			newInsts = append(newInsts, inst)
		}
	}

	b.Insts = newInsts
	return changed
}

// ----------------------------------------------------------------
// 개별 instruction 폴딩 시도
// ----------------------------------------------------------------

// tryFold: (folded bool, replacement *ir.Inst)
// folded=true, replacement=nil  → 제거
// folded=true, replacement=inst → 교체
// folded=false                  → 변경 없음
func tryFold(inst *ir.Inst) (bool, *ir.Inst) {
	switch inst.Kind {

	case ir.InstBinop:
		return foldBinop(inst)

	case ir.InstICmp:
		return foldICmp(inst)

	case ir.InstFCmp:
		return foldFCmp(inst)

	case ir.InstBrCond:
		return foldBrCond(inst)

	case ir.InstCast:
		return foldCast(inst)

	case ir.InstNeg:
		if isConstInt(inst.Operand) {
			return true, makeConst(inst.Result, inst.Type,
				-inst.Operand.IVal, 0, false)
		}
	}
	return false, nil
}

// ----------------------------------------------------------------
// Binop 폴딩
// ----------------------------------------------------------------

func foldBinop(inst *ir.Inst) (bool, *ir.Inst) {
	lhs, rhs := inst.LHS, inst.RHS
	isF := isConstFloat(lhs) || isConstFloat(rhs)

	// 양쪽 모두 상수
	if isConstInt(lhs) && isConstInt(rhs) {
		v := evalIntBinop(inst.Op, lhs.IVal, rhs.IVal)
		return true, makeConst(inst.Result, inst.Type, v, 0, false)
	}
	if isConstFloat(lhs) && isConstFloat(rhs) {
		v := evalFloatBinop(inst.Op, lhs.FVal, rhs.FVal)
		return true, makeConst(inst.Result, inst.Type, 0, v, true)
	}

	// 한쪽 상수 — identity / zero rule
	if !isF {
		switch inst.Op {
		case "add":
			if isZeroInt(rhs) { return true, makeMove(inst.Result, inst.Type, lhs) }
			if isZeroInt(lhs) { return true, makeMove(inst.Result, inst.Type, rhs) }
		case "sub":
			if isZeroInt(rhs) { return true, makeMove(inst.Result, inst.Type, lhs) }
			// sub x, x → 0 (같은 레지스터)
			if sameReg(lhs, rhs) { return true, makeConst(inst.Result, inst.Type, 0, 0, false) }
		case "mul":
			if isZeroInt(lhs) || isZeroInt(rhs) {
				return true, makeConst(inst.Result, inst.Type, 0, 0, false)
			}
			if isOneInt(rhs)  { return true, makeMove(inst.Result, inst.Type, lhs) }
			if isOneInt(lhs)  { return true, makeMove(inst.Result, inst.Type, rhs) }
		case "div":
			if isOneInt(rhs)  { return true, makeMove(inst.Result, inst.Type, lhs) }
			if isZeroInt(lhs) { return true, makeConst(inst.Result, inst.Type, 0, 0, false) }
		case "and":
			if isZeroInt(lhs) || isZeroInt(rhs) {
				return true, makeConst(inst.Result, inst.Type, 0, 0, false)
			}
		case "or":
			if isZeroInt(rhs) { return true, makeMove(inst.Result, inst.Type, lhs) }
			if isZeroInt(lhs) { return true, makeMove(inst.Result, inst.Type, rhs) }
		case "xor":
			if sameReg(lhs, rhs) { return true, makeConst(inst.Result, inst.Type, 0, 0, false) }
			if isZeroInt(rhs)    { return true, makeMove(inst.Result, inst.Type, lhs) }
		case "shl", "shr":
			if isZeroInt(rhs)    { return true, makeMove(inst.Result, inst.Type, lhs) }
			if isZeroInt(lhs)    { return true, makeConst(inst.Result, inst.Type, 0, 0, false) }
		}
	}
	return false, nil
}

func evalIntBinop(op string, l, r int64) int64 {
	switch op {
	case "add": return l + r
	case "sub": return l - r
	case "mul": return l * r
	case "div": if r != 0 { return l / r }; return 0
	case "rem": if r != 0 { return l % r }; return 0
	case "and": return l & r
	case "or":  return l | r
	case "xor": return l ^ r
	case "shl": return l << uint(r)
	case "shr": return l >> uint(r)
	}
	return 0
}

func evalFloatBinop(op string, l, r float64) float64 {
	switch op {
	case "fadd": return l + r
	case "fsub": return l - r
	case "fmul": return l * r
	case "fdiv": if r != 0 { return l / r }; return math.NaN()
	}
	return 0
}

// ----------------------------------------------------------------
// ICmp 폴딩
// ----------------------------------------------------------------

func foldICmp(inst *ir.Inst) (bool, *ir.Inst) {
	lhs, rhs := inst.LHS, inst.RHS

	// 같은 레지스터 비교
	if sameReg(lhs, rhs) {
		var result int64
		switch inst.Pred {
		case "eq", "le", "ge": result = 1
		default:               result = 0
		}
		return true, makeConst(inst.Result, ir.Bool(), result, 0, false)
	}

	// 양쪽 상수
	if isConstInt(lhs) && isConstInt(rhs) {
		var cmp bool
		l, r := lhs.IVal, rhs.IVal
		switch inst.Pred {
		case "eq":  cmp = l == r
		case "ne":  cmp = l != r
		case "lt":  cmp = l < r
		case "le":  cmp = l <= r
		case "gt":  cmp = l > r
		case "ge":  cmp = l >= r
		case "ult": cmp = uint64(l) < uint64(r)
		case "ule": cmp = uint64(l) <= uint64(r)
		case "ugt": cmp = uint64(l) > uint64(r)
		case "uge": cmp = uint64(l) >= uint64(r)
		}
		v := int64(0)
		if cmp { v = 1 }
		return true, makeConst(inst.Result, ir.Bool(), v, 0, false)
	}
	return false, nil
}

// ----------------------------------------------------------------
// FCmp 폴딩
// ----------------------------------------------------------------

func foldFCmp(inst *ir.Inst) (bool, *ir.Inst) {
	lhs, rhs := inst.LHS, inst.RHS
	if isConstFloat(lhs) && isConstFloat(rhs) {
		var cmp bool
		l, r := lhs.FVal, rhs.FVal
		switch inst.Pred {
		case "oeq": cmp = l == r
		case "one": cmp = l != r
		case "olt": cmp = l < r
		case "ole": cmp = l <= r
		case "ogt": cmp = l > r
		case "oge": cmp = l >= r
		}
		v := int64(0)
		if cmp { v = 1 }
		return true, makeConst(inst.Result, ir.Bool(), v, 0, false)
	}
	return false, nil
}

// ----------------------------------------------------------------
// BrCond 폴딩 → 무조건 Br
// ----------------------------------------------------------------

func foldBrCond(inst *ir.Inst) (bool, *ir.Inst) {
	cond := inst.Cond
	if cond.Kind == ir.ValConstBool {
		if cond.BVal {
			return true, ir.NewBr(inst.TrueLabel)
		}
		return true, ir.NewBr(inst.FalseLabel)
	}
	if cond.Kind == ir.ValConstInt {
		if cond.IVal != 0 {
			return true, ir.NewBr(inst.TrueLabel)
		}
		return true, ir.NewBr(inst.FalseLabel)
	}
	return false, nil
}

// ----------------------------------------------------------------
// Cast 폴딩
// ----------------------------------------------------------------

func foldCast(inst *ir.Inst) (bool, *ir.Inst) {
	v := inst.Operand
	if !isConstInt(v) && !isConstFloat(v) { return false, nil }

	switch inst.Op {
	case "trunc":
		if isConstInt(v) {
			iv := v.IVal
			switch inst.ToType.Name {
			case "i8",  "u8":  iv &= 0xFF
			case "i16", "u16": iv &= 0xFFFF
			case "i32", "u32": iv &= 0xFFFFFFFF
			}
			return true, makeConst(inst.Result, inst.ToType, iv, 0, false)
		}
	case "zext", "sext":
		if isConstInt(v) {
			return true, makeConst(inst.Result, inst.ToType, v.IVal, 0, false)
		}
	case "sitofp":
		if isConstInt(v) {
			return true, makeConst(inst.Result, inst.ToType, 0, float64(v.IVal), true)
		}
	case "fptosi":
		if isConstFloat(v) {
			return true, makeConst(inst.Result, inst.ToType, int64(v.FVal), 0, false)
		}
	case "bitcast", "ptrtoint", "inttoptr":
		if isConstInt(v) {
			return true, makeConst(inst.Result, inst.ToType, v.IVal, 0, false)
		}
	}
	return false, nil
}

// ----------------------------------------------------------------
// 헬퍼
// ----------------------------------------------------------------

func isConstInt(v *ir.Value) bool {
	return v != nil && v.Kind == ir.ValConstInt
}

func isConstFloat(v *ir.Value) bool {
	return v != nil && v.Kind == ir.ValConstFloat
}

func isZeroInt(v *ir.Value) bool {
	return isConstInt(v) && v.IVal == 0
}

func isOneInt(v *ir.Value) bool {
	return isConstInt(v) && v.IVal == 1
}

func sameReg(a, b *ir.Value) bool {
	return a != nil && b != nil &&
		a.Kind == ir.ValReg && b.Kind == ir.ValReg &&
		a.Name == b.Name
}

// makeConst: %result = const
func makeConst(result string, t *ir.Type, ival int64, fval float64, isF bool) *ir.Inst {
	var val *ir.Value
	if isF {
		val = ir.ConstFloat(fval, t)
	} else {
		val = ir.ConstInt(ival, t)
	}
	// binop add 0,0 형태로 상수를 "move"처럼 표현
	// 실제로는 ret/store 등이 직접 상수 Value를 참조하도록
	// move instruction: %r = add T val, 0  → 너무 번거로움
	// 대신: %r = add T 0, 0 처럼 쓰면 codegen이 상수를 직접 emit
	// 가장 깔끔한 방법: InstBinop add 0+0을 쓰지 말고
	// use-site에서 Value를 상수로 치환하는 방식
	// 여기서는 "move" 패턴: add %r, val, 0
	if isF {
		return ir.NewBinop("fadd", result, t, val, ir.ConstFloat(0, t))
	}
	return ir.NewBinop("add", result, t, val, ir.ConstInt(0, t))
}

// makeMove: %result = %src (copy)
func makeMove(result string, t *ir.Type, src *ir.Value) *ir.Inst {
	if src.Type != nil && (src.Type.Kind == ir.TyF32 || src.Type.Kind == ir.TyF64) {
		return ir.NewBinop("fadd", result, t, src, ir.ConstFloat(0, t))
	}
	return ir.NewBinop("add", result, t, src, ir.ConstInt(0, t))
}

