// Free IR 1.0 — Type System
package ir

import "fmt"

// ----------------------------------------------------------------
// TypeKind
// ----------------------------------------------------------------

type TypeKind int

const (
	TyI8 TypeKind = iota
	TyI16
	TyI32
	TyI64
	TyU8
	TyU16
	TyU32
	TyU64
	TyF32
	TyF64
	TyBool
	TyVoid
	TyPtr
	TyArray
	TySlice
	TyStruct
	TyFn
)

// ----------------------------------------------------------------
// Type
// ----------------------------------------------------------------

type Type struct {
	Kind     TypeKind
	Size     int    // bytes
	Name     string // primitive name or struct name

	// Ptr / Array / Slice
	Inner *Type

	// Array
	Count int

	// Struct
	Fields []StructField

	// Fn
	Params  []*Type
	RetType *Type
}

type StructField struct {
	Name string
	Type *Type
}

// ----------------------------------------------------------------
// Type constructors
// ----------------------------------------------------------------

func I8() *Type   { return &Type{Kind: TyI8, Size: 1, Name: "i8"} }
func I16() *Type  { return &Type{Kind: TyI16, Size: 2, Name: "i16"} }
func I32() *Type  { return &Type{Kind: TyI32, Size: 4, Name: "i32"} }
func I64() *Type  { return &Type{Kind: TyI64, Size: 8, Name: "i64"} }
func U8() *Type   { return &Type{Kind: TyU8, Size: 1, Name: "u8"} }
func U16() *Type  { return &Type{Kind: TyU16, Size: 2, Name: "u16"} }
func U32() *Type  { return &Type{Kind: TyU32, Size: 4, Name: "u32"} }
func U64() *Type  { return &Type{Kind: TyU64, Size: 8, Name: "u64"} }
func F32() *Type  { return &Type{Kind: TyF32, Size: 4, Name: "f32"} }
func F64() *Type  { return &Type{Kind: TyF64, Size: 8, Name: "f64"} }
func Bool() *Type { return &Type{Kind: TyBool, Size: 1, Name: "bool"} }
func Void() *Type { return &Type{Kind: TyVoid, Size: 0, Name: "void"} }

func Ptr(inner *Type) *Type {
	return &Type{Kind: TyPtr, Size: 8, Name: "ptr", Inner: inner}
}

func Array(elem *Type, count int) *Type {
	return &Type{Kind: TyArray, Size: elem.Size * count, Inner: elem, Count: count}
}

func Slice(elem *Type) *Type {
	return &Type{Kind: TySlice, Size: 16, Inner: elem}
}

func Struct(name string, fields []StructField) *Type {
	size := 0
	for _, f := range fields {
		size += f.Type.Size
	}
	return &Type{Kind: TyStruct, Name: name, Fields: fields, Size: size}
}

func FnType(params []*Type, ret *Type) *Type {
	return &Type{Kind: TyFn, Size: 8, Params: params, RetType: ret}
}

// ----------------------------------------------------------------
// String
// ----------------------------------------------------------------

func (t *Type) String() string {
	if t == nil {
		return "nil"
	}
	switch t.Kind {
	case TyPtr:
		return fmt.Sprintf("ptr<%s>", t.Inner)
	case TyArray:
		return fmt.Sprintf("array<%s,%d>", t.Inner, t.Count)
	case TySlice:
		return fmt.Sprintf("slice<%s>", t.Inner)
	case TyStruct:
		return "struct." + t.Name
	case TyFn:
		return "fn_ptr"
	default:
		return t.Name
	}
}

}

func NewRetVoid() *Inst {
	return &Inst{Kind: InstRetVoid}
}

func NewPhi(result string, t *Type, incoming []PhiIncoming) *Inst {
	return &Inst{Kind: InstPhi, Result: result, Type: t, Incoming: incoming}
}

// ----------------------------------------------------------------
// Inst.String()
// ----------------------------------------------------------------

func (inst *Inst) String() string {
	switch inst.Kind {
	case InstBinop:
		return fmt.Sprintf("%%%s = %s %s %s, %s",
			inst.Result, inst.Op, inst.Type, inst.LHS, inst.RHS)
	case InstNeg:
		return fmt.Sprintf("%%%s = neg %s %s", inst.Result, inst.Type, inst.Operand)
	case InstICmp:
		return fmt.Sprintf("%%%s = icmp %s %s %s, %s",
			inst.Result, inst.Pred, inst.LHS.Type, inst.LHS, inst.RHS)
	case InstFCmp:
		return fmt.Sprintf("%%%s = fcmp %s %s %s, %s",
			inst.Result, inst.Pred, inst.LHS.Type, inst.LHS, inst.RHS)
	case InstAlloca:
		return fmt.Sprintf("%%%s = alloca %s", inst.Result, inst.AllocType)
	case InstLoad:
		return fmt.Sprintf("%%%s = load %s %s", inst.Result, inst.Type, inst.Ptr)
	case InstStore:
		return fmt.Sprintf("store %s %s, %s", inst.Type, inst.Val, inst.Ptr)
	case InstGEP:
		return fmt.Sprintf("%%%s = gep %s %s, %s", inst.Result, inst.ElemType, inst.Ptr, inst.Idx)
	case InstCast:
		return fmt.Sprintf("%%%s = %s %s %s to %s",
			inst.Result, inst.Op, inst.FromType, inst.Operand, inst.ToType)
	case InstCall:
		args := make([]string, len(inst.Args))
		for i, a := range inst.Args { args[i] = a.String() }
		if inst.Result == "" {
			return fmt.Sprintf("call void %s(%s)", inst.Callee, strings.Join(args, ", "))
		}
		return fmt.Sprintf("%%%s = call %s %s(%s)",
			inst.Result, inst.Type, inst.Callee, strings.Join(args, ", "))
	case InstBr:
		return fmt.Sprintf("br label %%%s", inst.Target)
