   316→	asm     *Asm
   317→	// SSA 값 → 스택 슬롯 (rbp 기준 음수 offset)
   318→	slots   map[string]int32
   319→	nextOff int32 // 다음 슬롯 offset (음수 방향)
   320→	funcMap map[string]string // fn name → label
   321→}
   322→
   323→func newFuncCompiler(fn *ir.Function, funcMap map[string]string) *FuncCompiler {
   324→	return &FuncCompiler{
   325→		fn:      fn,
   326→		asm:     NewAsm(),
   327→		slots:   make(map[string]int32),
   328→		nextOff: 0,
   329→		funcMap: funcMap,
   330→	}
   331→}
   332→
   333→func (fc *FuncCompiler) slot(name string) int32 {
   334→	if off, ok := fc.slots[name]; ok { return off }
   335→	fc.nextOff -= 8
   336→	fc.slots[name] = fc.nextOff
   337→	return fc.nextOff
   338→}
   339→
   340→func (fc *FuncCompiler) stackSize() int32 {
   341→	// System V ABI: CALL 직전 RSP는 16바이트 정렬 필요.
   342→	// 프롤로그: push rbp (RSP -= 8) → sub rsp, N
   343→	// 조건: (8 + N) % 16 == 0 → N % 16 == 8
   344→	size := -fc.nextOff
   345→	if size <= 0 { size = 1 }
   346→	// N = ceil(size/16)*16 - 8 (최소 8)
   347→	aligned := ((size + 15) / 16) * 16
   348→	size = aligned - 8
   349→	if size <= 0 { size = 8 }
   350→	return size
   351→}
   352→
   353→// 값을 RAX에 로드
   354→func (fc *FuncCompiler) loadToRAX(v *ir.Value) {
   355→	switch v.Kind {
   356→	case ir.ValConstInt:
   357→		fc.asm.MovRI(RAX, v.IVal)
   358→	case ir.ValConstFloat:
   359→		// float64 비트 패턴을 int64로 재해석 후 MovRI
   360→		bits := int64(math.Float64bits(v.FVal))
   361→		fc.asm.MovRI(RAX, bits)
   362→	case ir.ValConstBool:
   363→		if v.BVal { fc.asm.MovRI32(RAX, 1) } else { fc.asm.MovRI32(RAX, 0) }
   364→	case ir.ValConstNull:
   365→		fc.asm.MovRI32(RAX, 0)
   366→	case ir.ValReg:
   367→		off := fc.slot(v.Name)
   368→		fc.asm.LoadStack(RAX, off)
   369→	case ir.ValGlobalRef:
