type ExprKind int

const (
	ExprInt    ExprKind = iota // 42
	ExprFloat                  // 3.14
	ExprBool                   // true / false
	ExprIdent                  // foo
	ExprBinop                  // a + b
	ExprUnary                  // -x, !x
	ExprCall                   // f(a, b)
	ExprCast                   // x as i32
	ExprString                 // "hello"
)

type Expr struct {
	Kind   ExprKind
	// Int/Float/Bool/String/Ident
	IVal   int64
	FVal   float64
	BVal   bool
	SVal   string
	// Binop
	Op     string
	Left   *Expr
	Right  *Expr
	// Unary
	Operand *Expr
	// Call
	Callee string
	Args   []*Expr
	// Cast
	ToType *AstType
}

// ----------------------------------------------------------------
// 문장 (Statement)
// ----------------------------------------------------------------

type StmtKind int

const (
	StmtLet    StmtKind = iota // let x: i64 = expr
	StmtAssign                 // x = expr
	StmtReturn                 // return expr
	StmtIf                     // if cond { } else { }
	StmtWhile                  // while cond { }
	StmtExpr                   // expr (함수 호출 등)
)

type Stmt struct {
	Kind StmtKind

	// Let
	VarName string
	VarType *AstType
	VarMut  bool
	Init    *Expr

	// Assign
	Target string
	Value  *Expr

	// Return
	RetVal *Expr

	// If
	Cond     *Expr
	Then     []*Stmt
	Else     []*Stmt

	// While
	Body     []*Stmt

	// Expr
	ExprVal  *Expr
}

// ----------------------------------------------------------------
// 최상위 선언 (Top-level)
// ----------------------------------------------------------------

type Param struct {
	Name string
	Type *AstType
}

type FnDecl struct {
	Name     string
	Params   []Param
	RetType  *AstType
	Body     []*Stmt
	IsExtern bool   // extern fn
}

type Program struct {
	Fns []*FnDecl
}

