func NewGEP(result string, elemType *Type, ptr, idx *Value) *Inst {
	return &Inst{Kind: InstGEP, Result: result, ElemType: elemType, Type: Ptr(elemType), Ptr: ptr, Idx: idx}
}

// FieldOffset: struct 타입에서 필드 인덱스의 바이트 오프셋 반환
// struct { x: i64, y: i64 } → FieldOffset(t, 0)=0, FieldOffset(t, 1)=8
func FieldOffset(t *Type, idx int) int {
	if t == nil || t.Kind != TyStruct { return 0 }
	off := 0
	for i, f := range t.Fields {
		if i == idx { return off }
		off += f.Type.Size
	}
	return off
}

// FieldType: struct 필드 타입 반환
func FieldType(t *Type, idx int) *Type {
	if t == nil || t.Kind != TyStruct { return I64() }
	if idx < 0 || idx >= len(t.Fields) { return I64() }
	return t.Fields[idx].Type
}

// NewGEPField: struct 필드 접근 GEP (idx는 필드 인덱스, 바이트 오프셋으로 변환)
// 결과: ptr을 baseaddr로 해석, fieldOffset을 상수 인덱스로 넘김
// interp/codegen은 ElemType.Size * idx 로 오프셋 계산하므로
// stride=1(byte), idx=offset 형태로 넘긴다
func NewGEPField(result string, structType *Type, fieldIdx int, ptr *Value) *Inst {
	offset := FieldOffset(structType, fieldIdx)
	ft := FieldType(structType, fieldIdx)
	byteType := &Type{Kind: TyI8, Size: 1, Name: "i8"}
	return &Inst{
		Kind:     InstGEP,
		Result:   result,
		ElemType: byteType,        // stride = 1 byte
		Type:     Ptr(ft),
		Ptr:      ptr,
		Idx:      ConstInt(int64(offset), I64()), // offset in bytes
	}
}

