// Free IR 1.0 — IR Nodes
package ir

import (
	"fmt"
	"strings"
)

// ----------------------------------------------------------------
// Value (SSA)
// ----------------------------------------------------------------

type ValueKind int

const (
	ValReg ValueKind = iota
	ValConstInt
	ValConstFloat
	ValConstBool
	ValConstNull
	ValGlobalRef
)

type Value struct {
	Kind  ValueKind
	Type  *Type
	Name  string  // reg name or global name
	IVal  int64
	FVal  float64
	BVal  bool
}

func Reg(name string, t *Type) *Value {
	return &Value{Kind: ValReg, Name: name, Type: t}
}

func ConstInt(v int64, t *Type) *Value {
	return &Value{Kind: ValConstInt, IVal: v, Type: t}
}

func ConstFloat(v float64, t *Type) *Value {
	return &Value{Kind: ValConstFloat, FVal: v, Type: t}
}

func ConstBool(v bool) *Value {
	b := 0
	if v { b = 1 }
	return &Value{Kind: ValConstBool, BVal: v, IVal: int64(b), Type: Bool()}
}

func ConstNull(t *Type) *Value {
	return &Value{Kind: ValConstNull, Type: t}
}

func GlobalRef(name string, t *Type) *Value {
	return &Value{Kind: ValGlobalRef, Name: name, Type: t}
}

func (v *Value) String() string {
	switch v.Kind {
	case ValReg:
		return "%" + v.Name
	case ValConstInt:
		return fmt.Sprintf("%d", v.IVal)
	case ValConstFloat:
		return fmt.Sprintf("%g", v.FVal)
	case ValConstBool:
		if v.BVal { return "true" }
		return "false"
	case ValConstNull:
		return "null"
	case ValGlobalRef:
		return "@" + v.Name
	}
	return "?"
}

// ----------------------------------------------------------------
// Instruction
// ----------------------------------------------------------------

type InstKind int

const (
	InstBinop InstKind = iota
	InstNeg
	InstICmp
	InstFCmp
	InstAlloca
	InstLoad
	InstStore
	InstGEP
	InstCast
	InstCall
	InstBr
	InstBrCond
	InstRet
	InstRetVoid
	InstPhi
)

type PhiIncoming struct {
	Val   *Value
	Block string
}

type Inst struct {
	Kind   InstKind
	Result string // SSA 결과 이름 ("" = void)
	Type   *Type  // 결과 타입

	// BinOp / ICmp / FCmp
	Op   string
	LHS  *Value
	RHS  *Value
	Pred string

	// Unary / Cast
	Operand  *Value
	FromType *Type
	ToType   *Type

	// Alloca
	AllocType *Type

	// Load / Store / GEP
	Ptr     *Value
	Val     *Value
	ElemType *Type
	Idx     *Value

	// Call
	Callee *Value
	Args   []*Value

	// Br
	Target     string
	Cond       *Value
	TrueLabel  string
	FalseLabel string

	// Phi
	Incoming []PhiIncoming
}

// ----------------------------------------------------------------
// Instruction constructors
// ----------------------------------------------------------------

func NewBinop(op, result string, t *Type, lhs, rhs *Value) *Inst {
	return &Inst{Kind: InstBinop, Op: op, Result: result, Type: t, LHS: lhs, RHS: rhs}
}

func NewNeg(result string, t *Type, operand *Value) *Inst {
	return &Inst{Kind: InstNeg, Result: result, Type: t, Operand: operand}
}

func NewICmp(pred, result string, t *Type, lhs, rhs *Value) *Inst {
	return &Inst{Kind: InstICmp, Pred: pred, Result: result, Type: Bool(), LHS: lhs, RHS: rhs}
}

func NewFCmp(pred, result string, t *Type, lhs, rhs *Value) *Inst {
	return &Inst{Kind: InstFCmp, Pred: pred, Result: result, Type: Bool(), LHS: lhs, RHS: rhs}
}

func NewAlloca(result string, allocType *Type) *Inst {
	return &Inst{Kind: InstAlloca, Result: result, AllocType: allocType, Type: Ptr(allocType)}
}

func NewLoad(result string, t *Type, ptr *Value) *Inst {
	return &Inst{Kind: InstLoad, Result: result, Type: t, Ptr: ptr}
}

func NewStore(t *Type, val, ptr *Value) *Inst {
	return &Inst{Kind: InstStore, Type: t, Val: val, Ptr: ptr}
}

func NewGEP(result string, elemType *Type, ptr, idx *Value) *Inst {
	return &Inst{Kind: InstGEP, Result: result, ElemType: elemType, Type: Ptr(elemType), Ptr: ptr, Idx: idx}
}

func NewCast(op, result string, fromType *Type, val *Value, toType *Type) *Inst {
	return &Inst{Kind: InstCast, Op: op, Result: result, FromType: fromType, Operand: val, ToType: toType, Type: toType}
}

func NewCall(result string, retType *Type, callee *Value, args []*Value) *Inst {
	return &Inst{Kind: InstCall, Result: result, Type: retType, Callee: callee, Args: args}
}

func NewBr(target string) *Inst {
	return &Inst{Kind: InstBr, Target: target}
}

func NewBrCond(cond *Value, trueLabel, falseLabel string) *Inst {
	return &Inst{Kind: InstBrCond, Cond: cond, TrueLabel: trueLabel, FalseLabel: falseLabel}
}

func NewRet(val *Value) *Inst {
	return &Inst{Kind: InstRet, Val: val}
}

func NewRetVoid() *Inst {
	return &Inst{Kind: InstRetVoid}
}

func NewPhi(result string, t *Type, incoming []PhiIncoming) *Inst {
	return &Inst{Kind: InstPhi, Result: result, Type: t, Incoming: incoming}
}

// ----------------------------------------------------------------
// Inst.String()
// ----------------------------------------------------------------

func (inst *Inst) String() string {
	switch inst.Kind {
	case InstBinop:
		return fmt.Sprintf("%%%s = %s %s %s, %s",
			inst.Result, inst.Op, inst.Type, inst.LHS, inst.RHS)
	case InstNeg:
		return fmt.Sprintf("%%%s = neg %s %s", inst.Result, inst.Type, inst.Operand)
	case InstICmp:
		return fmt.Sprintf("%%%s = icmp %s %s %s, %s",
			inst.Result, inst.Pred, inst.LHS.Type, inst.LHS, inst.RHS)
	case InstFCmp:
		return fmt.Sprintf("%%%s = fcmp %s %s %s, %s",
			inst.Result, inst.Pred, inst.LHS.Type, inst.LHS, inst.RHS)
	case InstAlloca:
		return fmt.Sprintf("%%%s = alloca %s", inst.Result, inst.AllocType)
	case InstLoad:
		return fmt.Sprintf("%%%s = load %s %s", inst.Result, inst.Type, inst.Ptr)
	case InstStore:
		return fmt.Sprintf("store %s %s, %s", inst.Type, inst.Val, inst.Ptr)
	case InstGEP:
		return fmt.Sprintf("%%%s = gep %s %s, %s", inst.Result, inst.ElemType, inst.Ptr, inst.Idx)
	case InstCast:
		return fmt.Sprintf("%%%s = %s %s %s to %s",
			inst.Result, inst.Op, inst.FromType, inst.Operand, inst.ToType)
	case InstCall:
		args := make([]string, len(inst.Args))
		for i, a := range inst.Args { args[i] = a.String() }
		if inst.Result == "" {
			return fmt.Sprintf("call void %s(%s)", inst.Callee, strings.Join(args, ", "))
		}
		return fmt.Sprintf("%%%s = call %s %s(%s)",
			inst.Result, inst.Type, inst.Callee, strings.Join(args, ", "))
	case InstBr:
		return fmt.Sprintf("br label %%%s", inst.Target)
	case InstBrCond:
		return fmt.Sprintf("br bool %s, label %%%s, label %%%s",
			inst.Cond, inst.TrueLabel, inst.FalseLabel)
	case InstRet:
		return fmt.Sprintf("ret %s %s", inst.Val.Type, inst.Val)
	case InstRetVoid:
		return "ret void"
	case InstPhi:
		parts := make([]string, len(inst.Incoming))
		for i, inc := range inst.Incoming {
			parts[i] = fmt.Sprintf("[%s, %%%s]", inc.Val, inc.Block)
		}
		return fmt.Sprintf("%%%s = phi %s %s",
			inst.Result, inst.Type, strings.Join(parts, ", "))
	}
	return "unknown"
}

// ----------------------------------------------------------------
// Block
// ----------------------------------------------------------------

type Block struct {
	Label string
	Insts []*Inst
}

func NewBlock(label string) *Block {
	return &Block{Label: label}
}

func (b *Block) Add(inst *Inst) {
	b.Insts = append(b.Insts, inst)
}

func (b *Block) IsTerminated() bool {
	if len(b.Insts) == 0 { return false }
	k := b.Insts[len(b.Insts)-1].Kind
	return k == InstBr || k == InstBrCond || k == InstRet || k == InstRetVoid
}

func (b *Block) String() string {
	var sb strings.Builder
	sb.WriteString(b.Label + ":\n")
	for _, inst := range b.Insts {
		sb.WriteString("  " + inst.String() + "\n")
	}
	return sb.String()
}

// ----------------------------------------------------------------
// Function
// ----------------------------------------------------------------

type Param struct {
	Name string
	Type *Type
}

type Function struct {
	Name     string
	Params   []Param
	RetType  *Type
	Blocks   []*Block
	IsExport bool
}

func NewFunction(name string, params []Param, retType *Type, isExport bool) *Function {
	return &Function{Name: name, Params: params, RetType: retType, IsExport: isExport}
}

func (f *Function) AddBlock(b *Block) {
	f.Blocks = append(f.Blocks, b)
}

func (f *Function) String() string {
	var sb strings.Builder
	prefix := "define fn"
	if f.IsExport { prefix = "export fn" }

	params := make([]string, len(f.Params))
	for i, p := range f.Params {
		params[i] = fmt.Sprintf("%s %%%s", p.Type, p.Name)
	}
	sb.WriteString(fmt.Sprintf("%s @%s(%s) -> %s {\n",
		prefix, f.Name, strings.Join(params, ", "), f.RetType))
	for _, b := range f.Blocks {
		sb.WriteString(b.String())
	}
	sb.WriteString("}")
	return sb.String()
}

// ExternFunction
type ExternFunction struct {
	Name       string
	ParamTypes []*Type
	RetType    *Type
	Variadic   bool
}

func (e *ExternFunction) String() string {
	params := make([]string, len(e.ParamTypes))
	for i, p := range e.ParamTypes { params[i] = p.String() }
	if e.Variadic { params = append(params, "...") }
	return fmt.Sprintf("extern fn @%s(%s) -> %s",
		e.Name, strings.Join(params, ", "), e.RetType)
}

// ----------------------------------------------------------------
// Global
// ----------------------------------------------------------------

type Global struct {
	Name string
	Type *Type
	Init interface{} // 상수값
}

// ----------------------------------------------------------------
// Module
// ----------------------------------------------------------------

type Module struct {
	Name      string
	Globals   []*Global
	Externs   []*ExternFunction
	Functions []*Function
}

func NewModule(name string) *Module {
	return &Module{Name: name}
}

func (m *Module) AddGlobal(g *Global) { m.Globals = append(m.Globals, g) }
func (m *Module) AddExtern(e *ExternFunction) { m.Externs = append(m.Externs, e) }
func (m *Module) AddFunction(f *Function) { m.Functions = append(m.Functions, f) }

func (m *Module) FuncMap() map[string]*Function {
	fm := make(map[string]*Function)
	for _, f := range m.Functions { fm[f.Name] = f }
	return fm
}

func (m *Module) String() string {
	var sb strings.Builder
	sb.WriteString("module @" + m.Name + "\n\n")
	for _, e := range m.Externs { sb.WriteString(e.String() + "\n") }
	if len(m.Externs) > 0 { sb.WriteString("\n") }
	for _, g := range m.Globals {
		sb.WriteString(fmt.Sprintf("global @%s: %s\n", g.Name, g.Type))
	}
	if len(m.Globals) > 0 { sb.WriteString("\n") }
	for _, f := range m.Functions { sb.WriteString(f.String() + "\n\n") }
	return sb.String()
}

