// slotN: N바이트 정렬 슬롯 할당 (struct alloca용)
func (fc *FuncCompiler) slotN(name string, n int32) int32 {
	if off, ok := fc.slots[name]; ok { return off }
	if n < 8 { n = 8 }
	// 8바이트 정렬
	aligned := (n + 7) &^ 7
	fc.nextOff -= aligned
	fc.slots[name] = fc.nextOff
	return fc.nextOff
}

