// fir Phase 3.4 — struct / GEP 검증
// IR을 직접 빌드하여 interp == native 검증
package main

import (
	"fmt"
	"fir/src/codegen"
	"fir/src/interp"
	"fir/src/ir"
)

var structPassed, structFailed int

// ----------------------------------------------------------------
// 헬퍼
// ----------------------------------------------------------------

// IR 직접 빌드 → interp 실행
func interpModule(mod *ir.Module, fnName string, args []interp.RVal) (int64, error) {
	r, err := interp.ExecModule(mod, fnName, args)
	if err != nil { return 0, err }
	return r.AsInt(), nil
}

// IR 직접 빌드 → native 실행
func nativeModule(mod *ir.Module, fnName string, args []interp.RVal) (int64, error) {
	cm, err := codegen.CompileModule(mod)
	if err != nil { return 0, err }
	argInts := make([]int64, len(args))
	for i, a := range args { argInts[i] = a.AsInt() }
	result, err := cm.ExecFunc(fnName, argInts...)
	if err != nil { return 0, err }
	return result, nil
}

func assertStruct(label string, mod *ir.Module, fnName string,
	args []interp.RVal, expected int64) {

	iv, err := interpModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp: %v\n", label, err)
		structFailed++
		return
	}
	nv, err := nativeModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | native: %v\n", label, err)
		structFailed++
		return
	}
	if iv != expected {
		fmt.Printf("[FAIL] %s | interp=%d expected=%d\n", label, iv, expected)
		structFailed++
		return
	}
	if nv != expected {
		fmt.Printf("[FAIL] %s | native=%d expected=%d\n", label, nv, expected)
		structFailed++
		return
	}
	fmt.Printf("[PASS] %s | interp=%d native=%d\n", label, iv, nv)
	structPassed++
}

// ----------------------------------------------------------------
// 테스트 케이스
// ----------------------------------------------------------------

// ST-1: Point{x:3, y:4} → return x
// struct Point { x: i64, y: i64 }
// fn f() -> i64 {
//   %p = alloca Point
//   gep field 0 → store 3
//   gep field 1 → store 4
//   load field 0 → return
// }
func buildPointX() *ir.Module {
	pointT := ir.Struct("Point", []ir.StructField{
		{Name: "x", Type: ir.I64()},
		{Name: "y", Type: ir.I64()},
	})

	fn := ir.NewFunction("f", ir.I64(), nil)
	b := ir.NewBlock("entry")

	// %p = alloca Point
	b.Add(ir.NewAlloca("p", pointT))

	// %px = gep field 0  (offset=0)
	b.Add(ir.NewGEPField("px", pointT, 0, ir.Reg("p", ir.Ptr(pointT))))
	// %py = gep field 1  (offset=8)
	b.Add(ir.NewGEPField("py", pointT, 1, ir.Reg("p", ir.Ptr(pointT))))

	// store 3 → %px
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(3, ir.I64()), ir.Reg("px", ir.Ptr(ir.I64()))))
	// store 4 → %py
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(4, ir.I64()), ir.Reg("py", ir.Ptr(ir.I64()))))

	// %vx = load i64 %px
	b.Add(ir.NewLoad("vx", ir.I64(), ir.Reg("px", ir.Ptr(ir.I64()))))
	b.Add(ir.NewRet(ir.Reg("vx", ir.I64())))

	fn.Blocks = append(fn.Blocks, b)
	mod := ir.NewModule("test_struct")
	mod.Functions = append(mod.Functions, fn)
	return mod
}

// ST-2: Point{x:3, y:4} → return y
func buildPointY() *ir.Module {
	pointT := ir.Struct("Point", []ir.StructField{
		{Name: "x", Type: ir.I64()},
		{Name: "y", Type: ir.I64()},
	})

	fn := ir.NewFunction("f", ir.I64(), nil)
	b := ir.NewBlock("entry")

	b.Add(ir.NewAlloca("p", pointT))
	b.Add(ir.NewGEPField("px", pointT, 0, ir.Reg("p", ir.Ptr(pointT))))
	b.Add(ir.NewGEPField("py", pointT, 1, ir.Reg("p", ir.Ptr(pointT))))
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(3, ir.I64()), ir.Reg("px", ir.Ptr(ir.I64()))))
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(4, ir.I64()), ir.Reg("py", ir.Ptr(ir.I64()))))

	b.Add(ir.NewLoad("vy", ir.I64(), ir.Reg("py", ir.Ptr(ir.I64()))))
	b.Add(ir.NewRet(ir.Reg("vy", ir.I64())))

	fn.Blocks = append(fn.Blocks, b)
	mod := ir.NewModule("test_struct")
	mod.Functions = append(mod.Functions, fn)
	return mod
}

// ST-3: Point{x:10, y:20} → return x + y
func buildPointSum() *ir.Module {
	pointT := ir.Struct("Point", []ir.StructField{
		{Name: "x", Type: ir.I64()},
		{Name: "y", Type: ir.I64()},
	})

	fn := ir.NewFunction("f", ir.I64(), nil)
	b := ir.NewBlock("entry")

	b.Add(ir.NewAlloca("p", pointT))
	b.Add(ir.NewGEPField("px", pointT, 0, ir.Reg("p", ir.Ptr(pointT))))
	b.Add(ir.NewGEPField("py", pointT, 1, ir.Reg("p", ir.Ptr(pointT))))
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(10, ir.I64()), ir.Reg("px", ir.Ptr(ir.I64()))))
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(20, ir.I64()), ir.Reg("py", ir.Ptr(ir.I64()))))

	b.Add(ir.NewLoad("vx", ir.I64(), ir.Reg("px", ir.Ptr(ir.I64()))))
	b.Add(ir.NewLoad("vy", ir.I64(), ir.Reg("py", ir.Ptr(ir.I64()))))
	b.Add(ir.NewBinop("add", "sum", ir.I64(), ir.Reg("vx", ir.I64()), ir.Reg("vy", ir.I64())))
	b.Add(ir.NewRet(ir.Reg("sum", ir.I64())))

	fn.Blocks = append(fn.Blocks, b)
	mod := ir.NewModule("test_struct")
	mod.Functions = append(mod.Functions, fn)
	return mod
}

// ST-4: Triple{a:1, b:2, c:3} → return c  (3-field struct)
func buildTripleC() *ir.Module {
	triT := ir.Struct("Triple", []ir.StructField{
		{Name: "a", Type: ir.I64()},
		{Name: "b", Type: ir.I64()},
		{Name: "c", Type: ir.I64()},
	})

	fn := ir.NewFunction("f", ir.I64(), nil)
	b := ir.NewBlock("entry")

	b.Add(ir.NewAlloca("t", triT))
	b.Add(ir.NewGEPField("ta", triT, 0, ir.Reg("t", ir.Ptr(triT))))
	b.Add(ir.NewGEPField("tb", triT, 1, ir.Reg("t", ir.Ptr(triT))))
	b.Add(ir.NewGEPField("tc", triT, 2, ir.Reg("t", ir.Ptr(triT))))
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(1, ir.I64()), ir.Reg("ta", ir.Ptr(ir.I64()))))
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(2, ir.I64()), ir.Reg("tb", ir.Ptr(ir.I64()))))
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(3, ir.I64()), ir.Reg("tc", ir.Ptr(ir.I64()))))

	b.Add(ir.NewLoad("vc", ir.I64(), ir.Reg("tc", ir.Ptr(ir.I64()))))
	b.Add(ir.NewRet(ir.Reg("vc", ir.I64())))

	fn.Blocks = append(fn.Blocks, b)
	mod := ir.NewModule("test_struct")
	mod.Functions = append(mod.Functions, fn)
	return mod
}

// ST-5: GEP 배열 인덱싱 (기존 GEP, 인덱스 = 런타임 값)
// int arr[3] = {10, 20, 30}; return arr[1];  → 20
func buildArrayIdx() *ir.Module {
	fn := ir.NewFunction("f", ir.I64(), nil)
	b := ir.NewBlock("entry")

	// arr = alloca [3 x i64] — 24바이트
	arrT := ir.Array(ir.I64(), 3)
	b.Add(ir.NewAlloca("arr", arrT))

	// arr[0] = gep stride=8, idx=0
	b.Add(ir.NewGEP("p0", ir.I64(), ir.Reg("arr", ir.Ptr(arrT)), ir.ConstInt(0, ir.I64())))
	b.Add(ir.NewGEP("p1", ir.I64(), ir.Reg("arr", ir.Ptr(arrT)), ir.ConstInt(1, ir.I64())))
	b.Add(ir.NewGEP("p2", ir.I64(), ir.Reg("arr", ir.Ptr(arrT)), ir.ConstInt(2, ir.I64())))

	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(10, ir.I64()), ir.Reg("p0", ir.Ptr(ir.I64()))))
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(20, ir.I64()), ir.Reg("p1", ir.Ptr(ir.I64()))))
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(30, ir.I64()), ir.Reg("p2", ir.Ptr(ir.I64()))))

	b.Add(ir.NewLoad("v", ir.I64(), ir.Reg("p1", ir.Ptr(ir.I64()))))
	b.Add(ir.NewRet(ir.Reg("v", ir.I64())))

	fn.Blocks = append(fn.Blocks, b)
	mod := ir.NewModule("test_arr")
	mod.Functions = append(mod.Functions, fn)
	return mod
}

// ST-6: struct 필드 수정 후 재읽기
// p.x = 5; p.x = p.x * 2; return p.x  → 10
func buildFieldUpdate() *ir.Module {
	pointT := ir.Struct("Point", []ir.StructField{
		{Name: "x", Type: ir.I64()},
		{Name: "y", Type: ir.I64()},
	})

	fn := ir.NewFunction("f", ir.I64(), nil)
	b := ir.NewBlock("entry")

	b.Add(ir.NewAlloca("p", pointT))
	b.Add(ir.NewGEPField("px", pointT, 0, ir.Reg("p", ir.Ptr(pointT))))

	// store 5
	b.Add(ir.NewStore(ir.I64(), ir.ConstInt(5, ir.I64()), ir.Reg("px", ir.Ptr(ir.I64()))))
	// load → *2 → store
	b.Add(ir.NewLoad("v0", ir.I64(), ir.Reg("px", ir.Ptr(ir.I64()))))
	b.Add(ir.NewBinop("mul", "v1", ir.I64(), ir.Reg("v0", ir.I64()), ir.ConstInt(2, ir.I64())))
	b.Add(ir.NewStore(ir.I64(), ir.Reg("v1", ir.I64()), ir.Reg("px", ir.Ptr(ir.I64()))))
	// load again
	b.Add(ir.NewLoad("v2", ir.I64(), ir.Reg("px", ir.Ptr(ir.I64()))))
	b.Add(ir.NewRet(ir.Reg("v2", ir.I64())))

	fn.Blocks = append(fn.Blocks, b)
	mod := ir.NewModule("test_struct")
	mod.Functions = append(mod.Functions, fn)
	return mod
}

