package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// Phase 7: Full Backpropagation Transformer
// 정확한 역전파: 근사 없음
//
// 수정 사항 (vs 구 버전):
//   - BlockCache: LN1/LN2 통계(mean, invStd) + residual 입력 저장
//   - LN backward: 정확한 수식 (근사 제거)
//   - Attention backward: 정확한 Q/K score gradient
//     softmax backward → dScore → dQ, dK (chain rule 완전)
//   - Embedding backward: seq 모든 위치 업데이트 (target만 아님)
//   - per-head 분리 forward/backward (헤드 평균 attnW → 헤드별 정확한 grad)
// ==================================================

// BlockCache Forward 시 중간 활성화 캐시
type BlockCache struct {
	X        [][]float64 // 블록 입력 [seqLen, d]  (embedding 출력)
	Q        [][]float64 // [seqLen, d]
	K        [][]float64 // [seqLen, d]
	V        [][]float64 // [seqLen, d]

	// 헤드별 attention weights [numHeads][seqLen][seqLen]
	AttnWPerHead [][][]float64

	AttnOut  [][]float64 // [seqLen, d]  softmax(QK^T/sqrt(dh)) @ V  concat
	MhaOut   [][]float64 // [seqLen, d]  AttnOut @ Wo

	// LN1: Add&Norm(X + MhaOut)
	Res1     [][]float64 // [seqLen, d]  X + MhaOut  (LN 입력)
	Ln1Mean  []float64   // [seqLen]
	Ln1InvStd []float64  // [seqLen]
	Ln1Out   [][]float64 // [seqLen, d]

	H        [][]float64 // FFN hidden [seqLen, ffn]  (post-GELU)
	HPreact  [][]float64 // FFN hidden pre-GELU [seqLen, ffn]
	FfnOut   [][]float64 // [seqLen, d]

	// LN2: Add&Norm(Ln1Out + FfnOut)
	Res2      [][]float64 // [seqLen, d]
	Ln2Mean   []float64   // [seqLen]
	Ln2InvStd []float64   // [seqLen]
	Ln2Out    [][]float64 // [seqLen, d]
}

// BPModel Full backprop Transformer (1-layer)
type BPModel struct {
	vocabSize int
	dModel    int
	dFFn      int
	numHeads  int
	dHead     int

	embedding [][]float64 // [vocab, d]
	Wq        [][]float64 // [d, d]
	Wk        [][]float64
	Wv        [][]float64
	Wo        [][]float64
	ln1Scale  []float64
	ln1Bias   []float64
	W1        [][]float64 // [d, ffn]
	b1        []float64
	W2        [][]float64 // [ffn, d]
	b2        []float64
	ln2Scale  []float64
	ln2Bias   []float64
	proj      [][]float64 // [d, vocab]
}

func newBPModel(vocabSize, d, ffn, numHeads int) *BPModel {
	scale  := math.Sqrt(2.0 / float64(d+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))
	vScale := math.Sqrt(2.0 / float64(vocabSize+d))
	return &BPModel{
		vocabSize: vocabSize,
		dModel:    d,
		dFFn:      ffn,
		numHeads:  numHeads,
		dHead:     d / numHeads,
		embedding: make2DRand(vocabSize, d, vScale),
		Wq:        make2DRand(d, d, scale),
		Wk:        make2DRand(d, d, scale),
		Wv:        make2DRand(d, d, scale),
		Wo:        make2DRand(d, d, scale),
		ln1Scale:  onesVec(d),
		ln1Bias:   zerosVec(d),
		W1:        make2DRand(d, ffn, fScale),
		b1:        zerosVec(ffn),
		W2:        make2DRand(ffn, d, fScale),
		b2:        zerosVec(d),
		ln2Scale:  onesVec(d),
		ln2Bias:   zerosVec(d),
		proj:      make2DRand(d, vocabSize, vScale),
	}
}

// ──────────────────────────────────────────────────────────
// LayerNorm helpers
// ──────────────────────────────────────────────────────────

func layerNormFull(x, scale, bias []float64) (out []float64, mean, invStd float64) {
	n := len(x)
	for _, v := range x { mean += v }
	mean /= float64(n)
	variance := 0.0
	for _, v := range x {
		d := v - mean
		variance += d * d
	}
	variance /= float64(n)
	invStd = 1.0 / math.Sqrt(variance+1e-5)
	out = make([]float64, n)
	for i, v := range x {
		out[i] = scale[i]*(v-mean)*invStd + bias[i]
	}
	return
}

// layerNormBackward: 정확한 수식
// dX = invStd/n * (n*dOut*scale - sum(dOut*scale) - xHat*sum(dOut*scale*xHat))
func layerNormBackward(dOut, x, scale []float64, mean, invStd float64) (dX, dScale, dBias []float64) {
	n := len(dOut)
	dScale = make([]float64, n)
	dBias  = make([]float64, n)
	dX     = make([]float64, n)

	xHat := make([]float64, n)
	for i := range x { xHat[i] = (x[i] - mean) * invStd }

	sumDS, sumDSX := 0.0, 0.0
	for i := range dOut {
		dScale[i] = dOut[i] * xHat[i]
		dBias[i]  = dOut[i]
		sumDS  += dOut[i] * scale[i]
		sumDSX += dOut[i] * scale[i] * xHat[i]
	}
	for i := range dOut {
		dX[i] = invStd / float64(n) * (float64(n)*dOut[i]*scale[i] - sumDS - xHat[i]*sumDSX)
	}
	return
}

// ──────────────────────────────────────────────────────────
// GELU & derivative
// ──────────────────────────────────────────────────────────

// geluGrad: dGELU/dx 정확한 수식
func geluGrad(x float64) float64 {
	c := math.Sqrt(2.0 / math.Pi)
	inner := c * (x + 0.044715*x*x*x)
	tanh  := math.Tanh(inner)
	dInner := c * (1.0 + 3*0.044715*x*x)
	return 0.5*(1+tanh) + 0.5*x*(1-tanh*tanh)*dInner
}

// ──────────────────────────────────────────────────────────
// Forward Pass
// ──────────────────────────────────────────────────────────

func (m *BPModel) forwardBP(seq []int) (logits []float64, cache *BlockCache) {
	seqLen := len(seq)
	d  := m.dModel
	nH := m.numHeads
	dH := m.dHead

	cache = &BlockCache{}

	// Embedding
	X := make([][]float64, seqLen)
	for i, tok := range seq {
		X[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(X[i], m.embedding[tok])
		}
	}
	cache.X = copyMat(X)

	// Linear projections
	cache.Q = matmul2D(X, m.Wq) // [seqLen, d]
	cache.K = matmul2D(X, m.Wk)
	cache.V = matmul2D(X, m.Wv)

	// Multi-head causal attention (헤드별 저장)
	attnOut := make([][]float64, seqLen)
	for i := range attnOut { attnOut[i] = make([]float64, d) }

	cache.AttnWPerHead = make([][][]float64, nH)
	for h := 0; h < nH; h++ {
		hS := h * dH
		cache.AttnWPerHead[h] = make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			cache.AttnWPerHead[h][i] = make([]float64, seqLen)
		}
		scale := 1.0 / math.Sqrt(float64(dH))
		for i := 0; i < seqLen; i++ {
			scores := make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += cache.Q[i][hS+k] * cache.K[j][hS+k]
				}
				scores[j] = dot * scale
			}
			for j := i + 1; j < seqLen; j++ { scores[j] = -1e9 }
			probs := softmax1D(scores)
			copy(cache.AttnWPerHead[h][i], probs)
			for j := 0; j < seqLen; j++ {
				for k := 0; k < dH; k++ {
					attnOut[i][hS+k] += probs[j] * cache.V[j][hS+k]
				}
			}
		}
	}
	cache.AttnOut = attnOut

	// Wo
	cache.MhaOut = matmul2D(attnOut, m.Wo)

	// Add & LN1
	res1 := make([][]float64, seqLen)
	for i := range res1 { res1[i] = addResidual(X[i], cache.MhaOut[i]) }
	cache.Res1     = res1
	cache.Ln1Mean  = make([]float64, seqLen)
	cache.Ln1InvStd = make([]float64, seqLen)
	cache.Ln1Out   = make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		cache.Ln1Out[i], cache.Ln1Mean[i], cache.Ln1InvStd[i] =
			layerNormFull(res1[i], m.ln1Scale, m.ln1Bias)
	}

	// FFN
	H       := make([][]float64, seqLen)
	HPreact := make([][]float64, seqLen)
	ffnOut  := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		pre := make([]float64, m.dFFn)
		h   := make([]float64, m.dFFn)
		for j := 0; j < m.dFFn; j++ {
			s := m.b1[j]
			for k := 0; k < d; k++ { s += cache.Ln1Out[i][k] * m.W1[k][j] }
			pre[j] = s
			h[j]   = geluActivation(s)
		}
		HPreact[i] = pre
		H[i]       = h
		out := make([]float64, d)
		for k := 0; k < d; k++ {
			s := m.b2[k]
			for j := 0; j < m.dFFn; j++ { s += h[j] * m.W2[j][k] }
			out[k] = s
		}
		ffnOut[i] = out
	}
	cache.H       = H
	cache.HPreact = HPreact
	cache.FfnOut  = ffnOut

	// Add & LN2
	res2 := make([][]float64, seqLen)
	for i := range res2 { res2[i] = addResidual(cache.Ln1Out[i], ffnOut[i]) }
	cache.Res2     = res2
	cache.Ln2Mean  = make([]float64, seqLen)
	cache.Ln2InvStd = make([]float64, seqLen)
	cache.Ln2Out   = make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		cache.Ln2Out[i], cache.Ln2Mean[i], cache.Ln2InvStd[i] =
			layerNormFull(res2[i], m.ln2Scale, m.ln2Bias)
	}

	// Logits (마지막 위치)
	last := cache.Ln2Out[seqLen-1]
	logits = make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		s := 0.0
		for k := 0; k < d; k++ { s += last[k] * m.proj[k][v] }
		logits[v] = s
	}
	return
}

// ──────────────────────────────────────────────────────────
// Backward Pass — 정확한 gradient, 근사 없음
// ──────────────────────────────────────────────────────────

func (m *BPModel) backwardStep(
	seq []int,
	targetTok int,
	cache *BlockCache,
	dLogits []float64,
	adam *BPAdams,
) {
	d       := m.dModel
	ffn     := m.dFFn
	seqLen  := len(seq)
	lastPos := seqLen - 1
	nH      := m.numHeads
	dH      := m.dHead

	// ── 1. proj backward ────────────────────────────────────
	// logits = Ln2Out[last] @ proj
	// dProj[k][v]  = Ln2Out[last][k] * dLogits[v]
	// dLn2Out[last][k] = sum_v proj[k][v] * dLogits[v]
	last := cache.Ln2Out[lastPos]
	flatProj  := flattenEmbedding(m.proj)
	gradsProj := make([]float64, d*m.vocabSize)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			gradsProj[k*m.vocabSize+v] = last[k] * dLogits[v]
		}
	}
	updProj := adam.proj.Step(flatProj, ClipGradient(gradsProj, 1.0))
	m.proj  = unflattenEmbedding(updProj, d, m.vocabSize)

	dLn2OutLast := make([]float64, d)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			dLn2OutLast[k] += m.proj[k][v] * dLogits[v]
		}
	}
	// dLn2Out: 마지막 위치만 non-zero
	dLn2Out := make([][]float64, seqLen)
	for i := range dLn2Out { dLn2Out[i] = make([]float64, d) }
	copy(dLn2Out[lastPos], dLn2OutLast)

	// ── 2. LN2 backward (정확) ──────────────────────────────
	// LN2 입력 = res2[i] = Ln1Out[i] + FfnOut[i]
	// dRes2 = dLn2Out → dLn1Out(ffn residual path), dFfnOut
	dRes2    := make([][]float64, seqLen)
	dLn2Scale := make([]float64, d)
	dLn2Bias  := make([]float64, d)
	for i := 0; i < seqLen; i++ {
		dx, dsc, dbs := layerNormBackward(
			dLn2Out[i], cache.Res2[i], m.ln2Scale,
			cache.Ln2Mean[i], cache.Ln2InvStd[i])
		dRes2[i] = dx
		for k := range dsc { dLn2Scale[k] += dsc[k]; dLn2Bias[k] += dbs[k] }
	}
	// residual 분기: dRes2 = d(Ln1Out + FfnOut) → 둘 다 동일
	dFfnOut      := dRes2              // FfnOut에 대한 gradient
	dLn1OutFromRes2 := copyMat(dRes2)  // Ln1Out 잔차 경로

	// ln2Scale / ln2Bias 업데이트
	updLn2Scale := adam.ln2Scale.Step(m.ln2Scale, dLn2Scale)
	updLn2Bias  := adam.ln2Bias.Step(m.ln2Bias,  dLn2Bias)
	m.ln2Scale, m.ln2Bias = updLn2Scale, updLn2Bias

	// ── 3. FFN backward ─────────────────────────────────────
	// FfnOut[i] = H[i] @ W2 + b2
	// H[i][j]   = GELU(Ln1Out[i] @ W1[:,j] + b1[j])
	flatW2    := flattenEmbedding(m.W2)
	gradsW2   := make([]float64, ffn*d)
	gradsb2   := make([]float64, d)
	dH        := make([][]float64, seqLen)  // dLoss/dH

	for i := 0; i < seqLen; i++ {
		dH[i] = make([]float64, ffn)
		for k := 0; k < d; k++ {
			gradsb2[k] += dFfnOut[i][k]
			for j := 0; j < ffn; j++ {
				gradsW2[j*d+k] += cache.H[i][j] * dFfnOut[i][k]
				dH[i][j]       += m.W2[j][k] * dFfnOut[i][k]
			}
		}
	}
	updW2 := adam.W2.Step(flatW2, ClipGradient(gradsW2, 1.0))
	m.W2  = unflattenEmbedding(updW2, ffn, d)
	updb2 := adam.b2.Step(m.b2, ClipGradient(gradsb2, 1.0))
	m.b2  = updb2

	// W1, b1: dH → dGELU(preact) → dLn1Out (FFN 경로)
	flatW1     := flattenEmbedding(m.W1)
	gradsW1    := make([]float64, d*ffn)
	gradsb1    := make([]float64, ffn)
	dLn1FromFFN := make([][]float64, seqLen)

	for i := 0; i < seqLen; i++ {
		dLn1FromFFN[i] = make([]float64, d)
		for j := 0; j < ffn; j++ {
			dg := dH[i][j] * geluGrad(cache.HPreact[i][j])  // 정확한 GELU 미분
			gradsb1[j] += dg
			for k := 0; k < d; k++ {
				gradsW1[k*ffn+j] += cache.Ln1Out[i][k] * dg
				dLn1FromFFN[i][k] += m.W1[k][j] * dg
			}
		}
	}
	updW1 := adam.W1.Step(flatW1, ClipGradient(gradsW1, 1.0))
	m.W1  = unflattenEmbedding(updW1, d, ffn)
	updb1 := adam.b1.Step(m.b1, ClipGradient(gradsb1, 1.0))
	m.b1  = updb1

	// dLn1Out = FFN잔차 경로 + FFN 직접 경로
	dLn1Out := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		dLn1Out[i] = make([]float64, d)
		for k := 0; k < d; k++ {
			dLn1Out[i][k] = dLn1OutFromRes2[i][k] + dLn1FromFFN[i][k]
		}
	}

	// ── 4. LN1 backward (정확) ──────────────────────────────
	// LN1 입력 = res1[i] = X[i] + MhaOut[i]
	dRes1     := make([][]float64, seqLen)
	dLn1Scale := make([]float64, d)
	dLn1Bias  := make([]float64, d)
	for i := 0; i < seqLen; i++ {
		dx, dsc, dbs := layerNormBackward(
			dLn1Out[i], cache.Res1[i], m.ln1Scale,
			cache.Ln1Mean[i], cache.Ln1InvStd[i])
		dRes1[i] = dx
		for k := range dsc { dLn1Scale[k] += dsc[k]; dLn1Bias[k] += dbs[k] }
	}
	// residual: dRes1 = d(X + MhaOut)
	dMhaOut  := copyMat(dRes1) // MhaOut에 대한 gradient
	dXFromLN1 := copyMat(dRes1) // X의 LN1 경로 gradient

	updLn1Scale := adam.ln1Scale.Step(m.ln1Scale, dLn1Scale)
	updLn1Bias  := adam.ln1Bias.Step(m.ln1Bias,  dLn1Bias)
	m.ln1Scale, m.ln1Bias = updLn1Scale, updLn1Bias

	// ── 5. Attention backward (정확) ────────────────────────
	// MhaOut = AttnOut @ Wo
	// dWo, dAttnOut

	flatWo    := flattenEmbedding(m.Wo)
	gradsWo   := make([]float64, d*d)
	dAttnOut  := make([][]float64, seqLen)
	for i := range dAttnOut { dAttnOut[i] = make([]float64, d) }

	for i := 0; i < seqLen; i++ {
		for k := 0; k < d; k++ {
			for j := 0; j < d; j++ {
				gradsWo[j*d+k] += cache.AttnOut[i][j] * dMhaOut[i][k]
				dAttnOut[i][j] += m.Wo[j][k] * dMhaOut[i][k]
			}
		}
	}
	updWo := adam.Wo.Step(flatWo, ClipGradient(gradsWo, 1.0))
	m.Wo  = unflattenEmbedding(updWo, d, d)

	// 헤드별 정확한 attention backward
	// dAttnOut[i][h*dH : (h+1)*dH] = sum_j(attnW[h][i][j] * dV[j][h*dH:])
	// dV[j][h*dH:] += sum_i(attnW[h][i][j] * dAttnOut[i][h*dH:])
	// dAttnW[h][i][j] = sum_k(dAttnOut[i][h*dH+k] * V[j][h*dH+k])
	// → softmax backward → dScore → dQ, dK

	dQ := make([][]float64, seqLen)
	dK := make([][]float64, seqLen)
	dV := make([][]float64, seqLen)
	for i := range dQ {
		dQ[i] = make([]float64, d)
		dK[i] = make([]float64, d)
		dV[i] = make([]float64, d)
	}

	attnScale := 1.0 / math.Sqrt(float64(dH))

	for h := 0; h < nH; h++ {
		hS := h * dH

		// dAttnW[h][i][j] = dot(dAttnOut[i][hS:hS+dH], V[j][hS:hS+dH])
		dAttnWh := make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			dAttnWh[i] = make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += dAttnOut[i][hS+k] * cache.V[j][hS+k]
				}
				dAttnWh[i][j] = dot
			}
		}

		// dV[j] += sum_i(attnW[h][i][j] * dAttnOut[i])
		for i := 0; i < seqLen; i++ {
			for j := 0; j <= i; j++ {
				for k := 0; k < dH; k++ {
					dV[j][hS+k] += cache.AttnWPerHead[h][i][j] * dAttnOut[i][hS+k]
				}
			}
		}

		// softmax backward: dScore[i][j] = attnW*(dAttnW - sum_k(attnW[k]*dAttnW[k]))
		// → dQ[i], dK[j]
		for i := 0; i < seqLen; i++ {
			aw := cache.AttnWPerHead[h][i]
			da := dAttnWh[i]

			// sum_k(aw[k] * da[k]) (causal: only j<=i)
			dot := 0.0
			for j := 0; j <= i; j++ { dot += aw[j] * da[j] }

			// dScore[i][j] = aw[j] * (da[j] - dot)
			for j := 0; j <= i; j++ {
				dScore := aw[j] * (da[j] - dot) * attnScale
				// dScore → dQ[i], dK[j]
				for k := 0; k < dH; k++ {
					dQ[i][hS+k] += dScore * cache.K[j][hS+k]
					dK[j][hS+k] += dScore * cache.Q[i][hS+k]
				}
			}
		}
	}

	// Wq, Wk, Wv backward: dW = X^T @ dQ/dK/dV
	flatWq  := flattenEmbedding(m.Wq)
	flatWk  := flattenEmbedding(m.Wk)
	flatWv  := flattenEmbedding(m.Wv)
	gradsWq := make([]float64, d*d)
	gradsWk := make([]float64, d*d)
	gradsWv := make([]float64, d*d)
	dXFromAttn := make([][]float64, seqLen)
	for i := range dXFromAttn { dXFromAttn[i] = make([]float64, d) }

	for i := 0; i < seqLen; i++ {
		for j := 0; j < d; j++ {
			for k := 0; k < d; k++ {
				gradsWq[j*d+k] += cache.X[i][j] * dQ[i][k]
				gradsWk[j*d+k] += cache.X[i][j] * dK[i][k]
				gradsWv[j*d+k] += cache.X[i][j] * dV[i][k]
				// dX = dQ @ Wq^T + dK @ Wk^T + dV @ Wv^T
				dXFromAttn[i][j] += m.Wq[j][k]*dQ[i][k] + m.Wk[j][k]*dK[i][k] + m.Wv[j][k]*dV[i][k]
			}
		}
	}
	updWq := adam.Wq.Step(flatWq, ClipGradient(gradsWq, 1.0))
	updWk := adam.Wk.Step(flatWk, ClipGradient(gradsWk, 1.0))
	updWv := adam.Wv.Step(flatWv, ClipGradient(gradsWv, 1.0))
	m.Wq = unflattenEmbedding(updWq, d, d)
	m.Wk = unflattenEmbedding(updWk, d, d)
	m.Wv = unflattenEmbedding(updWv, d, d)

	// ── 6. Embedding backward (모든 위치) ───────────────────
	// dX[i] = dXFromLN1[i] + dXFromAttn[i]
	// embedding[seq[i]] += dX[i]
	flatEmb  := flattenEmbedding(m.embedding)
	gradsEmb := make([]float64, m.vocabSize*d)

	for pos, tok := range seq {
		if tok >= m.vocabSize { continue }
		for k := 0; k < d; k++ {
			gradsEmb[tok*d+k] += dXFromLN1[pos][k] + dXFromAttn[pos][k]
		}
	}
	updEmb   := adam.emb.Step(flatEmb, ClipGradient(gradsEmb, 1.0))
	m.embedding = unflattenEmbedding(updEmb, m.vocabSize, d)
}

// ──────────────────────────────────────────────────────────
// Helpers
// ──────────────────────────────────────────────────────────

func copyMat(a [][]float64) [][]float64 {
	out := make([][]float64, len(a))
	for i := range a {
		out[i] = make([]float64, len(a[i]))
		copy(out[i], a[i])
	}
	return out
}

// ──────────────────────────────────────────────────────────
// Adam 묶음
// ──────────────────────────────────────────────────────────

type BPAdams struct {
	emb      *AdamState
	Wq       *AdamState
	Wk       *AdamState
	Wv       *AdamState
	Wo       *AdamState
	ln1Scale *AdamState
	ln1Bias  *AdamState
	W1       *AdamState
	b1       *AdamState
	W2       *AdamState
	b2       *AdamState
	ln2Scale *AdamState
	ln2Bias  *AdamState
	proj     *AdamState
}

func newBPAdams(lr float64, vocabSize, d, ffn int) *BPAdams {
	return &BPAdams{
		emb:      NewAdamState(lr, vocabSize*d),
		Wq:       NewAdamState(lr, d*d),
		Wk:       NewAdamState(lr, d*d),
		Wv:       NewAdamState(lr, d*d),
		Wo:       NewAdamState(lr, d*d),
		ln1Scale: NewAdamState(lr, d),
		ln1Bias:  NewAdamState(lr, d),
		W1:       NewAdamState(lr, d*ffn),
		b1:       NewAdamState(lr, ffn),
		W2:       NewAdamState(lr, ffn*d),
		b2:       NewAdamState(lr, d),
		ln2Scale: NewAdamState(lr, d),
		ln2Bias:  NewAdamState(lr, d),
		proj:     NewAdamState(lr, d*vocabSize),
	}
}

func (a *BPAdams) setLR(lr float64) {
	a.emb.LearningRate = lr
	a.Wq.LearningRate  = lr
	a.Wk.LearningRate  = lr
	a.Wv.LearningRate  = lr
	a.Wo.LearningRate  = lr
	a.ln1Scale.LearningRate = lr
	a.ln1Bias.LearningRate  = lr
	a.W1.LearningRate  = lr
	a.b1.LearningRate  = lr
	a.W2.LearningRate  = lr
	a.b2.LearningRate  = lr
	a.ln2Scale.LearningRate = lr
	a.ln2Bias.LearningRate  = lr
	a.proj.LearningRate = lr
}

// ──────────────────────────────────────────────────────────
// 학습 루프
// ──────────────────────────────────────────────────────────

func trainBP() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 7: Full Backpropagation Transformer (정확한 역전파)  ║")
	fmt.Println("║  수정: LN/Attn/Emb backward 근사 완전 제거                ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	fmt.Println("[1/5] Loading data...")
	tokens, vocab, err := tokenizeRealData("data/real_corpus_large.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}
	fmt.Printf("✅ Loaded %d tokens, vocab=%d\n\n", len(tokens), len(vocab))

	if len(tokens) < 64 {
		fmt.Println("⚠️  데이터 너무 적음 — data/corpus.txt 사용")
		tokens, vocab, err = tokenizeRealData("data/corpus.txt")
		if err != nil {
			fmt.Printf("❌ corpus.txt: %v\n", err)
			return
		}
		fmt.Printf("✅ corpus.txt: %d tokens, vocab=%d\n\n", len(tokens), len(vocab))
	}

	d       := 128
	ffn     := 512
	numHeads := 4

	fmt.Println("[2/5] Creating BP Transformer...")
	model := newBPModel(len(vocab), d, ffn, numHeads)
	paramCount := len(vocab)*d + d*d*4 + d*ffn*2 + d*len(vocab)
	fmt.Printf("✅ d=%d, heads=%d, FFN=%d, params=~%dk\n\n", d, numHeads, ffn, paramCount/1000)

	fmt.Println("[3/5] Initializing Adam (14 instances)...")
	adam := newBPAdams(0.0003, len(vocab), d, ffn)
	fmt.Printf("✅ Adam ready (lr=0.0003, β1=0.9, β2=0.999)\n\n")

	seqLen      := 32
	epochs      := 20
	numBatches  := 500
	warmupSteps := 300
	totalSteps  := epochs * numBatches

	fmt.Println("[4/5] Training config:")
	fmt.Printf("   seqLen=%d, epochs=%d, batches/epoch=%d\n", seqLen, epochs, numBatches)
	fmt.Printf("   warmup=%d steps, cosine decay\n\n", warmupSteps)

	fmt.Println("[5/5] Training...")
	fmt.Println("══════════════════════════════════════════════════════════════")

	losses  := make([]float64, 0, epochs)
	bestPPL := math.MaxFloat64

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < numBatches; batch++ {
			startIdx := rand.Intn(len(tokens) - seqLen - 1)
			seq       := tokens[startIdx : startIdx+seqLen]
			targetTok := tokens[startIdx+seqLen]

			logits, cache := model.forwardBP(seq)
			probs := softmax1D(logits)

			loss := math.Log(float64(len(vocab))) // fallback
			if targetTok < len(probs) && probs[targetTok] > 1e-10 {
				loss = -math.Log(probs[targetTok])
			}
			epochLoss += loss

			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if targetTok < len(dLogits) { dLogits[targetTok] -= 1.0 }

			// LR schedule: warmup + cosine
			step := (epoch-1)*numBatches + batch + 1
			var lr float64
			if step < warmupSteps {
				lr = 0.0003 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0003 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adam.setLR(lr)

			model.backwardStep(seq, targetTok, cache, dLogits, adam)

			if batch%100 == 0 {
				avg := epochLoss / float64(batch+1)
				fmt.Printf("Epoch %02d/%d  batch %3d/%d  loss=%.4f  ppl=%.1f  lr=%.5f\r",
					epoch, epochs, batch+1, numBatches, avg, math.Exp(avg), lr)
			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses  = append(losses, avgLoss)
		ppl     := math.Exp(avgLoss)
		marker  := ""
		if ppl < bestPPL {
			bestPPL = ppl
			marker  = " ★ best"
		}
		fmt.Printf("\n✅ Epoch %02d: loss=%.4f  PPL=%.2f%s\n", epoch, avgLoss, ppl, marker)
	}

	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("📊 학습 곡선:")
	for i, l := range losses {
		bar := ""
		if len(losses) > 1 && losses[0] > l {
			n := int((losses[0]-l)/losses[0]*40)
			for j := 0; j < n; j++ { bar += "█" }
		}
		fmt.Printf("  Epoch %02d: %s %.4f (PPL: %.2f)\n", i+1, bar, l, math.Exp(l))
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp  := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Phase 7 결과:\n")
		fmt.Printf("   Initial PPL: %.2f\n", iPPL)
		fmt.Printf("   Final PPL:   %.2f\n", fPPL)
		fmt.Printf("   Best PPL:    %.2f ★\n", bestPPL)
		if imp > 0 {
			fmt.Printf("   개선:        %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   악화:        %.1f%% ⚠️\n\n", -imp)
		}
	}
}

package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// Phase 7: Full Backpropagation Transformer
// 정확한 역전파: 근사 없음
//
// 수정 사항 (vs 구 버전):
//   - BlockCache: LN1/LN2 통계(mean, invStd) + residual 입력 저장
//   - LN backward: 정확한 수식 (근사 제거)
//   - Attention backward: 정확한 Q/K score gradient
//     softmax backward → dScore → dQ, dK (chain rule 완전)
//   - Embedding backward: seq 모든 위치 업데이트 (target만 아님)
//   - per-head 분리 forward/backward (헤드 평균 attnW → 헤드별 정확한 grad)
// ==================================================

// BlockCache Forward 시 중간 활성화 캐시
type BlockCache struct {
	X        [][]float64 // 블록 입력 [seqLen, d]  (embedding 출력)
	Q        [][]float64 // [seqLen, d]
	K        [][]float64 // [seqLen, d]
	V        [][]float64 // [seqLen, d]

	// 헤드별 attention weights [numHeads][seqLen][seqLen]
	AttnWPerHead [][][]float64

	AttnOut  [][]float64 // [seqLen, d]  softmax(QK^T/sqrt(dh)) @ V  concat
	MhaOut   [][]float64 // [seqLen, d]  AttnOut @ Wo

	// LN1: Add&Norm(X + MhaOut)
	Res1     [][]float64 // [seqLen, d]  X + MhaOut  (LN 입력)
	Ln1Mean  []float64   // [seqLen]
	Ln1InvStd []float64  // [seqLen]
	Ln1Out   [][]float64 // [seqLen, d]

	H        [][]float64 // FFN hidden [seqLen, ffn]  (post-GELU)
	HPreact  [][]float64 // FFN hidden pre-GELU [seqLen, ffn]
	FfnOut   [][]float64 // [seqLen, d]

	// LN2: Add&Norm(Ln1Out + FfnOut)
	Res2      [][]float64 // [seqLen, d]
	Ln2Mean   []float64   // [seqLen]
	Ln2InvStd []float64   // [seqLen]
	Ln2Out    [][]float64 // [seqLen, d]
}

// BPModel Full backprop Transformer (1-layer)
type BPModel struct {
	vocabSize int
	dModel    int
	dFFn      int
	numHeads  int
	dHead     int

	embedding [][]float64 // [vocab, d]
	Wq        [][]float64 // [d, d]
	Wk        [][]float64
	Wv        [][]float64
	Wo        [][]float64
	ln1Scale  []float64
	ln1Bias   []float64
	W1        [][]float64 // [d, ffn]
	b1        []float64
	W2        [][]float64 // [ffn, d]
	b2        []float64
	ln2Scale  []float64
	ln2Bias   []float64
	proj      [][]float64 // [d, vocab]
}

func newBPModel(vocabSize, d, ffn, numHeads int) *BPModel {
	scale  := math.Sqrt(2.0 / float64(d+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))
	vScale := math.Sqrt(2.0 / float64(vocabSize+d))
	return &BPModel{
		vocabSize: vocabSize,
		dModel:    d,
		dFFn:      ffn,
		numHeads:  numHeads,
		dHead:     d / numHeads,
		embedding: make2DRand(vocabSize, d, vScale),
		Wq:        make2DRand(d, d, scale),
		Wk:        make2DRand(d, d, scale),
		Wv:        make2DRand(d, d, scale),
		Wo:        make2DRand(d, d, scale),
		ln1Scale:  onesVec(d),
		ln1Bias:   zerosVec(d),
		W1:        make2DRand(d, ffn, fScale),
		b1:        zerosVec(ffn),
		W2:        make2DRand(ffn, d, fScale),
		b2:        zerosVec(d),
		ln2Scale:  onesVec(d),
		ln2Bias:   zerosVec(d),
		proj:      make2DRand(d, vocabSize, vScale),
	}
}

// ──────────────────────────────────────────────────────────
// LayerNorm helpers
// ──────────────────────────────────────────────────────────

func layerNormFull(x, scale, bias []float64) (out []float64, mean, invStd float64) {
	n := len(x)
	for _, v := range x { mean += v }
	mean /= float64(n)
	variance := 0.0
	for _, v := range x {
		d := v - mean
		variance += d * d
	}
	variance /= float64(n)
	invStd = 1.0 / math.Sqrt(variance+1e-5)
	out = make([]float64, n)
	for i, v := range x {
		out[i] = scale[i]*(v-mean)*invStd + bias[i]
	}
	return
}

// layerNormBackward: 정확한 수식
// dX = invStd/n * (n*dOut*scale - sum(dOut*scale) - xHat*sum(dOut*scale*xHat))
func layerNormBackward(dOut, x, scale []float64, mean, invStd float64) (dX, dScale, dBias []float64) {
	n := len(dOut)
	dScale = make([]float64, n)
	dBias  = make([]float64, n)
	dX     = make([]float64, n)

	xHat := make([]float64, n)
	for i := range x { xHat[i] = (x[i] - mean) * invStd }

	sumDS, sumDSX := 0.0, 0.0
	for i := range dOut {
		dScale[i] = dOut[i] * xHat[i]
		dBias[i]  = dOut[i]
		sumDS  += dOut[i] * scale[i]
		sumDSX += dOut[i] * scale[i] * xHat[i]
	}
	for i := range dOut {
		dX[i] = invStd / float64(n) * (float64(n)*dOut[i]*scale[i] - sumDS - xHat[i]*sumDSX)
	}
	return
}

// ──────────────────────────────────────────────────────────
// GELU & derivative
// ──────────────────────────────────────────────────────────

// geluGrad: dGELU/dx 정확한 수식
func geluGrad(x float64) float64 {
	c := math.Sqrt(2.0 / math.Pi)
	inner := c * (x + 0.044715*x*x*x)
	tanh  := math.Tanh(inner)
	dInner := c * (1.0 + 3*0.044715*x*x)
	return 0.5*(1+tanh) + 0.5*x*(1-tanh*tanh)*dInner
}

// ──────────────────────────────────────────────────────────
// Forward Pass
// ──────────────────────────────────────────────────────────

func (m *BPModel) forwardBP(seq []int) (logits []float64, cache *BlockCache) {
	seqLen := len(seq)
	d  := m.dModel
	nH := m.numHeads
	dH := m.dHead

	cache = &BlockCache{}

	// Embedding
	X := make([][]float64, seqLen)
	for i, tok := range seq {
		X[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(X[i], m.embedding[tok])
		}
	}
	cache.X = copyMat(X)

	// Linear projections
	cache.Q = matmul2D(X, m.Wq) // [seqLen, d]
	cache.K = matmul2D(X, m.Wk)
	cache.V = matmul2D(X, m.Wv)

	// Multi-head causal attention (헤드별 저장)
	attnOut := make([][]float64, seqLen)
	for i := range attnOut { attnOut[i] = make([]float64, d) }

	cache.AttnWPerHead = make([][][]float64, nH)
	for h := 0; h < nH; h++ {
		hS := h * dH
		cache.AttnWPerHead[h] = make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			cache.AttnWPerHead[h][i] = make([]float64, seqLen)
		}
		scale := 1.0 / math.Sqrt(float64(dH))
		for i := 0; i < seqLen; i++ {
			scores := make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += cache.Q[i][hS+k] * cache.K[j][hS+k]
				}
				scores[j] = dot * scale
			}
			for j := i + 1; j < seqLen; j++ { scores[j] = -1e9 }
			probs := softmax1D(scores)
			copy(cache.AttnWPerHead[h][i], probs)
			for j := 0; j < seqLen; j++ {
				for k := 0; k < dH; k++ {
					attnOut[i][hS+k] += probs[j] * cache.V[j][hS+k]
				}
			}
		}
	}
	cache.AttnOut = attnOut

	// Wo
	cache.MhaOut = matmul2D(attnOut, m.Wo)

	// Add & LN1
	res1 := make([][]float64, seqLen)
	for i := range res1 { res1[i] = addResidual(X[i], cache.MhaOut[i]) }
	cache.Res1     = res1
	cache.Ln1Mean  = make([]float64, seqLen)
	cache.Ln1InvStd = make([]float64, seqLen)
	cache.Ln1Out   = make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		cache.Ln1Out[i], cache.Ln1Mean[i], cache.Ln1InvStd[i] =
			layerNormFull(res1[i], m.ln1Scale, m.ln1Bias)
	}

	// FFN
	H       := make([][]float64, seqLen)
	HPreact := make([][]float64, seqLen)
	ffnOut  := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		pre := make([]float64, m.dFFn)
		h   := make([]float64, m.dFFn)
		for j := 0; j < m.dFFn; j++ {
			s := m.b1[j]
			for k := 0; k < d; k++ { s += cache.Ln1Out[i][k] * m.W1[k][j] }
			pre[j] = s
			h[j]   = geluActivation(s)
		}
		HPreact[i] = pre
		H[i]       = h
		out := make([]float64, d)
		for k := 0; k < d; k++ {
			s := m.b2[k]
			for j := 0; j < m.dFFn; j++ { s += h[j] * m.W2[j][k] }
			out[k] = s
		}
		ffnOut[i] = out
	}
	cache.H       = H
	cache.HPreact = HPreact
	cache.FfnOut  = ffnOut

	// Add & LN2
	res2 := make([][]float64, seqLen)
	for i := range res2 { res2[i] = addResidual(cache.Ln1Out[i], ffnOut[i]) }
	cache.Res2     = res2
	cache.Ln2Mean  = make([]float64, seqLen)
	cache.Ln2InvStd = make([]float64, seqLen)
	cache.Ln2Out   = make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		cache.Ln2Out[i], cache.Ln2Mean[i], cache.Ln2InvStd[i] =
			layerNormFull(res2[i], m.ln2Scale, m.ln2Bias)
	}

	// Logits (마지막 위치)
	last := cache.Ln2Out[seqLen-1]
	logits = make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		s := 0.0
		for k := 0; k < d; k++ { s += last[k] * m.proj[k][v] }
		logits[v] = s
	}
	return
}

// ──────────────────────────────────────────────────────────
// Backward Pass — 정확한 gradient, 근사 없음
// ──────────────────────────────────────────────────────────

func (m *BPModel) backwardStep(
	seq []int,
	targetTok int,
	cache *BlockCache,
	dLogits []float64,
	adam *BPAdams,
) {
	d       := m.dModel
	ffn     := m.dFFn
	seqLen  := len(seq)
	lastPos := seqLen - 1
	nH      := m.numHeads
	dH      := m.dHead

	// ── 1. proj backward ────────────────────────────────────
	// logits = Ln2Out[last] @ proj
	// dProj[k][v]  = Ln2Out[last][k] * dLogits[v]
	// dLn2Out[last][k] = sum_v proj[k][v] * dLogits[v]
	last := cache.Ln2Out[lastPos]
	flatProj  := flattenEmbedding(m.proj)
	gradsProj := make([]float64, d*m.vocabSize)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			gradsProj[k*m.vocabSize+v] = last[k] * dLogits[v]
		}
	}
	updProj := adam.proj.Step(flatProj, ClipGradient(gradsProj, 1.0))
	m.proj  = unflattenEmbedding(updProj, d, m.vocabSize)

	dLn2OutLast := make([]float64, d)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			dLn2OutLast[k] += m.proj[k][v] * dLogits[v]
		}
	}
	// dLn2Out: 마지막 위치만 non-zero
	dLn2Out := make([][]float64, seqLen)
	for i := range dLn2Out { dLn2Out[i] = make([]float64, d) }
	copy(dLn2Out[lastPos], dLn2OutLast)

	// ── 2. LN2 backward (정확) ──────────────────────────────
	// LN2 입력 = res2[i] = Ln1Out[i] + FfnOut[i]
	// dRes2 = dLn2Out → dLn1Out(ffn residual path), dFfnOut
	dRes2    := make([][]float64, seqLen)
	dLn2Scale := make([]float64, d)
	dLn2Bias  := make([]float64, d)
	for i := 0; i < seqLen; i++ {
		dx, dsc, dbs := layerNormBackward(
			dLn2Out[i], cache.Res2[i], m.ln2Scale,
			cache.Ln2Mean[i], cache.Ln2InvStd[i])
		dRes2[i] = dx
		for k := range dsc { dLn2Scale[k] += dsc[k]; dLn2Bias[k] += dbs[k] }
	}
	// residual 분기: dRes2 = d(Ln1Out + FfnOut) → 둘 다 동일
	dFfnOut      := dRes2              // FfnOut에 대한 gradient
	dLn1OutFromRes2 := copyMat(dRes2)  // Ln1Out 잔차 경로

	// ln2Scale / ln2Bias 업데이트
	updLn2Scale := adam.ln2Scale.Step(m.ln2Scale, dLn2Scale)
	updLn2Bias  := adam.ln2Bias.Step(m.ln2Bias,  dLn2Bias)
	m.ln2Scale, m.ln2Bias = updLn2Scale, updLn2Bias

	// ── 3. FFN backward ─────────────────────────────────────
	// FfnOut[i] = H[i] @ W2 + b2
	// H[i][j]   = GELU(Ln1Out[i] @ W1[:,j] + b1[j])
	flatW2    := flattenEmbedding(m.W2)
	gradsW2   := make([]float64, ffn*d)
	gradsb2   := make([]float64, d)
	dHidden   := make([][]float64, seqLen)  // dLoss/dH (FFN hidden)

	for i := 0; i < seqLen; i++ {
		dHidden[i] = make([]float64, ffn)
		for k := 0; k < d; k++ {
			gradsb2[k] += dFfnOut[i][k]
			for j := 0; j < ffn; j++ {
				gradsW2[j*d+k] += cache.H[i][j] * dFfnOut[i][k]
				dHidden[i][j]  += m.W2[j][k] * dFfnOut[i][k]
			}
		}
	}
	updW2 := adam.W2.Step(flatW2, ClipGradient(gradsW2, 1.0))
	m.W2  = unflattenEmbedding(updW2, ffn, d)
	updb2 := adam.b2.Step(m.b2, ClipGradient(gradsb2, 1.0))
	m.b2  = updb2

	// W1, b1: dHidden → dGELU(preact) → dLn1Out (FFN 경로)
	flatW1      := flattenEmbedding(m.W1)
	gradsW1     := make([]float64, d*ffn)
	gradsb1     := make([]float64, ffn)
	dLn1FromFFN := make([][]float64, seqLen)

	for i := 0; i < seqLen; i++ {
		dLn1FromFFN[i] = make([]float64, d)
		for j := 0; j < ffn; j++ {
			dg := dHidden[i][j] * geluGrad(cache.HPreact[i][j])  // 정확한 GELU 미분
			gradsb1[j] += dg
			for k := 0; k < d; k++ {
				gradsW1[k*ffn+j] += cache.Ln1Out[i][k] * dg
				dLn1FromFFN[i][k] += m.W1[k][j] * dg
			}
		}
	}
	updW1 := adam.W1.Step(flatW1, ClipGradient(gradsW1, 1.0))
	m.W1  = unflattenEmbedding(updW1, d, ffn)
	updb1 := adam.b1.Step(m.b1, ClipGradient(gradsb1, 1.0))
	m.b1  = updb1

	// dLn1Out = FFN잔차 경로 + FFN 직접 경로
	dLn1Out := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		dLn1Out[i] = make([]float64, d)
		for k := 0; k < d; k++ {
			dLn1Out[i][k] = dLn1OutFromRes2[i][k] + dLn1FromFFN[i][k]
		}
	}

	// ── 4. LN1 backward (정확) ──────────────────────────────
	// LN1 입력 = res1[i] = X[i] + MhaOut[i]
	dRes1     := make([][]float64, seqLen)
	dLn1Scale := make([]float64, d)
	dLn1Bias  := make([]float64, d)
	for i := 0; i < seqLen; i++ {
		dx, dsc, dbs := layerNormBackward(
			dLn1Out[i], cache.Res1[i], m.ln1Scale,
			cache.Ln1Mean[i], cache.Ln1InvStd[i])
		dRes1[i] = dx
		for k := range dsc { dLn1Scale[k] += dsc[k]; dLn1Bias[k] += dbs[k] }
	}
	// residual: dRes1 = d(X + MhaOut)
	dMhaOut  := copyMat(dRes1) // MhaOut에 대한 gradient
	dXFromLN1 := copyMat(dRes1) // X의 LN1 경로 gradient

	updLn1Scale := adam.ln1Scale.Step(m.ln1Scale, dLn1Scale)
	updLn1Bias  := adam.ln1Bias.Step(m.ln1Bias,  dLn1Bias)
	m.ln1Scale, m.ln1Bias = updLn1Scale, updLn1Bias

	// ── 5. Attention backward (정확) ────────────────────────
	// MhaOut = AttnOut @ Wo
	// dWo, dAttnOut

	flatWo    := flattenEmbedding(m.Wo)
	gradsWo   := make([]float64, d*d)
	dAttnOut  := make([][]float64, seqLen)
	for i := range dAttnOut { dAttnOut[i] = make([]float64, d) }

	for i := 0; i < seqLen; i++ {
		for k := 0; k < d; k++ {
			for j := 0; j < d; j++ {
				gradsWo[j*d+k] += cache.AttnOut[i][j] * dMhaOut[i][k]
				dAttnOut[i][j] += m.Wo[j][k] * dMhaOut[i][k]
			}
		}
	}
	updWo := adam.Wo.Step(flatWo, ClipGradient(gradsWo, 1.0))
	m.Wo  = unflattenEmbedding(updWo, d, d)

	// 헤드별 정확한 attention backward
	// dAttnOut[i][h*dH : (h+1)*dH] = sum_j(attnW[h][i][j] * dV[j][h*dH:])
	// dV[j][h*dH:] += sum_i(attnW[h][i][j] * dAttnOut[i][h*dH:])
	// dAttnW[h][i][j] = sum_k(dAttnOut[i][h*dH+k] * V[j][h*dH+k])
	// → softmax backward → dScore → dQ, dK

	dQ := make([][]float64, seqLen)
	dK := make([][]float64, seqLen)
	dV := make([][]float64, seqLen)
	for i := range dQ {
		dQ[i] = make([]float64, d)
		dK[i] = make([]float64, d)
		dV[i] = make([]float64, d)
	}

	attnScale := 1.0 / math.Sqrt(float64(dH))

	for h := 0; h < nH; h++ {
		hS := h * dH

		// dAttnW[h][i][j] = dot(dAttnOut[i][hS:hS+dH], V[j][hS:hS+dH])
		dAttnWh := make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			dAttnWh[i] = make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += dAttnOut[i][hS+k] * cache.V[j][hS+k]
				}
				dAttnWh[i][j] = dot
			}
		}

		// dV[j] += sum_i(attnW[h][i][j] * dAttnOut[i])
		for i := 0; i < seqLen; i++ {
			for j := 0; j <= i; j++ {
				for k := 0; k < dH; k++ {
					dV[j][hS+k] += cache.AttnWPerHead[h][i][j] * dAttnOut[i][hS+k]
				}
			}
		}

		// softmax backward: dScore[i][j] = attnW*(dAttnW - sum_k(attnW[k]*dAttnW[k]))
		// → dQ[i], dK[j]
		for i := 0; i < seqLen; i++ {
			aw := cache.AttnWPerHead[h][i]
			da := dAttnWh[i]

			// sum_k(aw[k] * da[k]) (causal: only j<=i)
			dot := 0.0
			for j := 0; j <= i; j++ { dot += aw[j] * da[j] }

			// dScore[i][j] = aw[j] * (da[j] - dot)
			for j := 0; j <= i; j++ {
				dScore := aw[j] * (da[j] - dot) * attnScale
				// dScore → dQ[i], dK[j]
				for k := 0; k < dH; k++ {
					dQ[i][hS+k] += dScore * cache.K[j][hS+k]
					dK[j][hS+k] += dScore * cache.Q[i][hS+k]
				}
			}
		}
	}

	// Wq, Wk, Wv backward: dW = X^T @ dQ/dK/dV
	flatWq  := flattenEmbedding(m.Wq)
	flatWk  := flattenEmbedding(m.Wk)
	flatWv  := flattenEmbedding(m.Wv)
	gradsWq := make([]float64, d*d)
	gradsWk := make([]float64, d*d)
	gradsWv := make([]float64, d*d)
	dXFromAttn := make([][]float64, seqLen)
	for i := range dXFromAttn { dXFromAttn[i] = make([]float64, d) }

	for i := 0; i < seqLen; i++ {
		for j := 0; j < d; j++ {
			for k := 0; k < d; k++ {
				gradsWq[j*d+k] += cache.X[i][j] * dQ[i][k]
				gradsWk[j*d+k] += cache.X[i][j] * dK[i][k]
				gradsWv[j*d+k] += cache.X[i][j] * dV[i][k]
				// dX = dQ @ Wq^T + dK @ Wk^T + dV @ Wv^T
				dXFromAttn[i][j] += m.Wq[j][k]*dQ[i][k] + m.Wk[j][k]*dK[i][k] + m.Wv[j][k]*dV[i][k]
			}
		}
	}
	updWq := adam.Wq.Step(flatWq, ClipGradient(gradsWq, 1.0))
	updWk := adam.Wk.Step(flatWk, ClipGradient(gradsWk, 1.0))
	updWv := adam.Wv.Step(flatWv, ClipGradient(gradsWv, 1.0))
	m.Wq = unflattenEmbedding(updWq, d, d)
	m.Wk = unflattenEmbedding(updWk, d, d)
	m.Wv = unflattenEmbedding(updWv, d, d)

	// ── 6. Embedding backward (모든 위치) ───────────────────
	// dX[i] = dXFromLN1[i] + dXFromAttn[i]
	// embedding[seq[i]] += dX[i]
	flatEmb  := flattenEmbedding(m.embedding)
	gradsEmb := make([]float64, m.vocabSize*d)

	for pos, tok := range seq {
		if tok >= m.vocabSize { continue }
		for k := 0; k < d; k++ {
			gradsEmb[tok*d+k] += dXFromLN1[pos][k] + dXFromAttn[pos][k]
		}
	}
	updEmb   := adam.emb.Step(flatEmb, ClipGradient(gradsEmb, 1.0))
	m.embedding = unflattenEmbedding(updEmb, m.vocabSize, d)
}

// ──────────────────────────────────────────────────────────
// Helpers
// ──────────────────────────────────────────────────────────

func copyMat(a [][]float64) [][]float64 {
	out := make([][]float64, len(a))
	for i := range a {
		out[i] = make([]float64, len(a[i]))
		copy(out[i], a[i])
	}
	return out
}

// ──────────────────────────────────────────────────────────
// Adam 묶음
// ──────────────────────────────────────────────────────────

type BPAdams struct {
	emb      *AdamState
	Wq       *AdamState
	Wk       *AdamState
	Wv       *AdamState
	Wo       *AdamState
	ln1Scale *AdamState
	ln1Bias  *AdamState
	W1       *AdamState
	b1       *AdamState
	W2       *AdamState
	b2       *AdamState
	ln2Scale *AdamState
	ln2Bias  *AdamState
	proj     *AdamState
}

func newBPAdams(lr float64, vocabSize, d, ffn int) *BPAdams {
	return &BPAdams{
		emb:      NewAdamState(lr, vocabSize*d),
		Wq:       NewAdamState(lr, d*d),
		Wk:       NewAdamState(lr, d*d),
		Wv:       NewAdamState(lr, d*d),
		Wo:       NewAdamState(lr, d*d),
		ln1Scale: NewAdamState(lr, d),
		ln1Bias:  NewAdamState(lr, d),
		W1:       NewAdamState(lr, d*ffn),
		b1:       NewAdamState(lr, ffn),
		W2:       NewAdamState(lr, ffn*d),
		b2:       NewAdamState(lr, d),
		ln2Scale: NewAdamState(lr, d),
		ln2Bias:  NewAdamState(lr, d),
		proj:     NewAdamState(lr, d*vocabSize),
	}
}

func (a *BPAdams) setLR(lr float64) {
	a.emb.LearningRate = lr
	a.Wq.LearningRate  = lr
	a.Wk.LearningRate  = lr
	a.Wv.LearningRate  = lr
	a.Wo.LearningRate  = lr
	a.ln1Scale.LearningRate = lr
	a.ln1Bias.LearningRate  = lr
	a.W1.LearningRate  = lr
	a.b1.LearningRate  = lr
	a.W2.LearningRate  = lr
	a.b2.LearningRate  = lr
	a.ln2Scale.LearningRate = lr
	a.ln2Bias.LearningRate  = lr
	a.proj.LearningRate = lr
}

// ──────────────────────────────────────────────────────────
// 학습 루프
// ──────────────────────────────────────────────────────────

func trainBP() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 7: Full Backpropagation Transformer (정확한 역전파)  ║")
	fmt.Println("║  수정: LN/Attn/Emb backward 근사 완전 제거                ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	fmt.Println("[1/5] Loading data...")
	tokens, vocab, err := tokenizeRealData("data/real_corpus_large.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}
	fmt.Printf("✅ Loaded %d tokens, vocab=%d\n\n", len(tokens), len(vocab))

	if len(tokens) < 64 {
		fmt.Println("⚠️  데이터 너무 적음 — data/corpus.txt 사용")
		tokens, vocab, err = tokenizeRealData("data/corpus.txt")
		if err != nil {
			fmt.Printf("❌ corpus.txt: %v\n", err)
			return
		}
		fmt.Printf("✅ corpus.txt: %d tokens, vocab=%d\n\n", len(tokens), len(vocab))
	}

	d       := 128
	ffn     := 512
	numHeads := 4

	fmt.Println("[2/5] Creating BP Transformer...")
	model := newBPModel(len(vocab), d, ffn, numHeads)
	paramCount := len(vocab)*d + d*d*4 + d*ffn*2 + d*len(vocab)
	fmt.Printf("✅ d=%d, heads=%d, FFN=%d, params=~%dk\n\n", d, numHeads, ffn, paramCount/1000)

	fmt.Println("[3/5] Initializing Adam (14 instances)...")
	adam := newBPAdams(0.0003, len(vocab), d, ffn)
	fmt.Printf("✅ Adam ready (lr=0.0003, β1=0.9, β2=0.999)\n\n")

	seqLen      := 32
	epochs      := 20
	numBatches  := 500
	warmupSteps := 300
	totalSteps  := epochs * numBatches

	fmt.Println("[4/5] Training config:")
	fmt.Printf("   seqLen=%d, epochs=%d, batches/epoch=%d\n", seqLen, epochs, numBatches)
	fmt.Printf("   warmup=%d steps, cosine decay\n\n", warmupSteps)

	fmt.Println("[5/5] Training...")
	fmt.Println("══════════════════════════════════════════════════════════════")

	losses  := make([]float64, 0, epochs)
	bestPPL := math.MaxFloat64

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < numBatches; batch++ {
			startIdx := rand.Intn(len(tokens) - seqLen - 1)
			seq       := tokens[startIdx : startIdx+seqLen]
			targetTok := tokens[startIdx+seqLen]

			logits, cache := model.forwardBP(seq)
			probs := softmax1D(logits)

			loss := math.Log(float64(len(vocab))) // fallback
			if targetTok < len(probs) && probs[targetTok] > 1e-10 {
				loss = -math.Log(probs[targetTok])
			}
			epochLoss += loss

			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if targetTok < len(dLogits) { dLogits[targetTok] -= 1.0 }

			// LR schedule: warmup + cosine
			step := (epoch-1)*numBatches + batch + 1
			var lr float64
			if step < warmupSteps {
				lr = 0.0003 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0003 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adam.setLR(lr)

			model.backwardStep(seq, targetTok, cache, dLogits, adam)

			if batch%100 == 0 {
				avg := epochLoss / float64(batch+1)
				fmt.Printf("Epoch %02d/%d  batch %3d/%d  loss=%.4f  ppl=%.1f  lr=%.5f\r",
					epoch, epochs, batch+1, numBatches, avg, math.Exp(avg), lr)
			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses  = append(losses, avgLoss)
		ppl     := math.Exp(avgLoss)
		marker  := ""
		if ppl < bestPPL {
			bestPPL = ppl
			marker  = " ★ best"
		}
		fmt.Printf("\n✅ Epoch %02d: loss=%.4f  PPL=%.2f%s\n", epoch, avgLoss, ppl, marker)
	}

	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("📊 학습 곡선:")
	for i, l := range losses {
		bar := ""
		if len(losses) > 1 && losses[0] > l {
			n := int((losses[0]-l)/losses[0]*40)
			for j := 0; j < n; j++ { bar += "█" }
		}
		fmt.Printf("  Epoch %02d: %s %.4f (PPL: %.2f)\n", i+1, bar, l, math.Exp(l))
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp  := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Phase 7 결과:\n")
		fmt.Printf("   Initial PPL: %.2f\n", iPPL)
		fmt.Printf("   Final PPL:   %.2f\n", fPPL)
		fmt.Printf("   Best PPL:    %.2f ★\n", bestPPL)
		if imp > 0 {
			fmt.Printf("   개선:        %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   악화:        %.1f%% ⚠️\n\n", -imp)
		}
	}
}

package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// Phase 7: Full Backpropagation Transformer
// 정확한 역전파: 근사 없음
//
// 수정 사항 (vs 구 버전):
//   - BlockCache: LN1/LN2 통계(mean, invStd) + residual 입력 저장
//   - LN backward: 정확한 수식 (근사 제거)
//   - Attention backward: 정확한 Q/K score gradient
//     softmax backward → dScore → dQ, dK (chain rule 완전)
//   - Embedding backward: seq 모든 위치 업데이트 (target만 아님)
//   - per-head 분리 forward/backward (헤드 평균 attnW → 헤드별 정확한 grad)
// ==================================================

// BlockCache Forward 시 중간 활성화 캐시
type BlockCache struct {
	X        [][]float64 // 블록 입력 [seqLen, d]  (embedding 출력)
	Q        [][]float64 // [seqLen, d]
	K        [][]float64 // [seqLen, d]
	V        [][]float64 // [seqLen, d]

	// 헤드별 attention weights [numHeads][seqLen][seqLen]
	AttnWPerHead [][][]float64

	AttnOut  [][]float64 // [seqLen, d]  softmax(QK^T/sqrt(dh)) @ V  concat
	MhaOut   [][]float64 // [seqLen, d]  AttnOut @ Wo

	// LN1: Add&Norm(X + MhaOut)
	Res1     [][]float64 // [seqLen, d]  X + MhaOut  (LN 입력)
	Ln1Mean  []float64   // [seqLen]
	Ln1InvStd []float64  // [seqLen]
	Ln1Out   [][]float64 // [seqLen, d]

	H        [][]float64 // FFN hidden [seqLen, ffn]  (post-GELU)
	HPreact  [][]float64 // FFN hidden pre-GELU [seqLen, ffn]
	FfnOut   [][]float64 // [seqLen, d]

	// LN2: Add&Norm(Ln1Out + FfnOut)
	Res2      [][]float64 // [seqLen, d]
	Ln2Mean   []float64   // [seqLen]
	Ln2InvStd []float64   // [seqLen]
	Ln2Out    [][]float64 // [seqLen, d]
}

// BPModel Full backprop Transformer (1-layer)
type BPModel struct {
	vocabSize int
	dModel    int
	dFFn      int
	numHeads  int
	dHead     int

	embedding [][]float64 // [vocab, d]
	Wq        [][]float64 // [d, d]
	Wk        [][]float64
	Wv        [][]float64
	Wo        [][]float64
	ln1Scale  []float64
	ln1Bias   []float64
	W1        [][]float64 // [d, ffn]
	b1        []float64
	W2        [][]float64 // [ffn, d]
	b2        []float64
	ln2Scale  []float64
	ln2Bias   []float64
	proj      [][]float64 // [d, vocab]
}

func newBPModel(vocabSize, d, ffn, numHeads int) *BPModel {
	scale  := math.Sqrt(2.0 / float64(d+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))
	vScale := math.Sqrt(2.0 / float64(vocabSize+d))
	return &BPModel{
		vocabSize: vocabSize,
		dModel:    d,
		dFFn:      ffn,
		numHeads:  numHeads,
		dHead:     d / numHeads,
		embedding: make2DRand(vocabSize, d, vScale),
		Wq:        make2DRand(d, d, scale),
		Wk:        make2DRand(d, d, scale),
		Wv:        make2DRand(d, d, scale),
		Wo:        make2DRand(d, d, scale),
		ln1Scale:  onesVec(d),
		ln1Bias:   zerosVec(d),
		W1:        make2DRand(d, ffn, fScale),
		b1:        zerosVec(ffn),
		W2:        make2DRand(ffn, d, fScale),
		b2:        zerosVec(d),
		ln2Scale:  onesVec(d),
		ln2Bias:   zerosVec(d),
		proj:      make2DRand(d, vocabSize, vScale),
	}
}

// ──────────────────────────────────────────────────────────
// LayerNorm helpers
// ──────────────────────────────────────────────────────────

func layerNormFull(x, scale, bias []float64) (out []float64, mean, invStd float64) {
	n := len(x)
	for _, v := range x { mean += v }
	mean /= float64(n)
	variance := 0.0
	for _, v := range x {
		d := v - mean
		variance += d * d
	}
	variance /= float64(n)
	invStd = 1.0 / math.Sqrt(variance+1e-5)
	out = make([]float64, n)
	for i, v := range x {
		out[i] = scale[i]*(v-mean)*invStd + bias[i]
	}
	return
}

// layerNormBackward: 정확한 수식
// dX = invStd/n * (n*dOut*scale - sum(dOut*scale) - xHat*sum(dOut*scale*xHat))
func layerNormBackward(dOut, x, scale []float64, mean, invStd float64) (dX, dScale, dBias []float64) {
	n := len(dOut)
	dScale = make([]float64, n)
	dBias  = make([]float64, n)
	dX     = make([]float64, n)

	xHat := make([]float64, n)
	for i := range x { xHat[i] = (x[i] - mean) * invStd }

	sumDS, sumDSX := 0.0, 0.0
	for i := range dOut {
		dScale[i] = dOut[i] * xHat[i]
		dBias[i]  = dOut[i]
		sumDS  += dOut[i] * scale[i]
		sumDSX += dOut[i] * scale[i] * xHat[i]
	}
	for i := range dOut {
		dX[i] = invStd / float64(n) * (float64(n)*dOut[i]*scale[i] - sumDS - xHat[i]*sumDSX)
	}
	return
}

// ──────────────────────────────────────────────────────────
// GELU & derivative
// ──────────────────────────────────────────────────────────

// geluGrad: dGELU/dx 정확한 수식
func geluGrad(x float64) float64 {
	c := math.Sqrt(2.0 / math.Pi)
	inner := c * (x + 0.044715*x*x*x)
	tanh  := math.Tanh(inner)
	dInner := c * (1.0 + 3*0.044715*x*x)
	return 0.5*(1+tanh) + 0.5*x*(1-tanh*tanh)*dInner
}

// ──────────────────────────────────────────────────────────
// Forward Pass
// ──────────────────────────────────────────────────────────

func (m *BPModel) forwardBP(seq []int) (logits []float64, cache *BlockCache) {
	seqLen := len(seq)
	d  := m.dModel
	nH := m.numHeads
	dH := m.dHead

	cache = &BlockCache{}

	// Embedding
	X := make([][]float64, seqLen)
	for i, tok := range seq {
		X[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(X[i], m.embedding[tok])
		}
	}
	cache.X = copyMat(X)

	// Linear projections
	cache.Q = matmul2D(X, m.Wq) // [seqLen, d]
	cache.K = matmul2D(X, m.Wk)
	cache.V = matmul2D(X, m.Wv)

	// Multi-head causal attention (헤드별 저장)
	attnOut := make([][]float64, seqLen)
	for i := range attnOut { attnOut[i] = make([]float64, d) }

	cache.AttnWPerHead = make([][][]float64, nH)
	for h := 0; h < nH; h++ {
		hS := h * dH
		cache.AttnWPerHead[h] = make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			cache.AttnWPerHead[h][i] = make([]float64, seqLen)
		}
		scale := 1.0 / math.Sqrt(float64(dH))
		for i := 0; i < seqLen; i++ {
			scores := make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += cache.Q[i][hS+k] * cache.K[j][hS+k]
				}
				scores[j] = dot * scale
			}
			for j := i + 1; j < seqLen; j++ { scores[j] = -1e9 }
			probs := softmax1D(scores)
			copy(cache.AttnWPerHead[h][i], probs)
			for j := 0; j < seqLen; j++ {
				for k := 0; k < dH; k++ {
					attnOut[i][hS+k] += probs[j] * cache.V[j][hS+k]
				}
			}
		}
	}
	cache.AttnOut = attnOut

	// Wo
	cache.MhaOut = matmul2D(attnOut, m.Wo)

	// Add & LN1
	res1 := make([][]float64, seqLen)
	for i := range res1 { res1[i] = addResidual(X[i], cache.MhaOut[i]) }
	cache.Res1     = res1
	cache.Ln1Mean  = make([]float64, seqLen)
	cache.Ln1InvStd = make([]float64, seqLen)
	cache.Ln1Out   = make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		cache.Ln1Out[i], cache.Ln1Mean[i], cache.Ln1InvStd[i] =
			layerNormFull(res1[i], m.ln1Scale, m.ln1Bias)
	}

	// FFN
	H       := make([][]float64, seqLen)
	HPreact := make([][]float64, seqLen)
	ffnOut  := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		pre := make([]float64, m.dFFn)
		h   := make([]float64, m.dFFn)
		for j := 0; j < m.dFFn; j++ {
			s := m.b1[j]
			for k := 0; k < d; k++ { s += cache.Ln1Out[i][k] * m.W1[k][j] }
			pre[j] = s
			h[j]   = geluActivation(s)
		}
		HPreact[i] = pre
		H[i]       = h
		out := make([]float64, d)
		for k := 0; k < d; k++ {
			s := m.b2[k]
			for j := 0; j < m.dFFn; j++ { s += h[j] * m.W2[j][k] }
			out[k] = s
		}
		ffnOut[i] = out
	}
	cache.H       = H
	cache.HPreact = HPreact
	cache.FfnOut  = ffnOut

	// Add & LN2
	res2 := make([][]float64, seqLen)
	for i := range res2 { res2[i] = addResidual(cache.Ln1Out[i], ffnOut[i]) }
	cache.Res2     = res2
	cache.Ln2Mean  = make([]float64, seqLen)
	cache.Ln2InvStd = make([]float64, seqLen)
	cache.Ln2Out   = make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		cache.Ln2Out[i], cache.Ln2Mean[i], cache.Ln2InvStd[i] =
			layerNormFull(res2[i], m.ln2Scale, m.ln2Bias)
	}

	// Logits (마지막 위치)
	last := cache.Ln2Out[seqLen-1]
	logits = make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		s := 0.0
		for k := 0; k < d; k++ { s += last[k] * m.proj[k][v] }
		logits[v] = s
	}
	return
}

// ──────────────────────────────────────────────────────────
// Backward Pass — 정확한 gradient, 근사 없음
// ──────────────────────────────────────────────────────────

func (m *BPModel) backwardStep(
	seq []int,
	targetTok int,
	cache *BlockCache,
	dLogits []float64,
	adam *BPAdams,
) {
	d       := m.dModel
	ffn     := m.dFFn
	seqLen  := len(seq)
	lastPos := seqLen - 1
	nH      := m.numHeads
	dH      := m.dHead

	// ── 1. proj backward ────────────────────────────────────
	// logits = Ln2Out[last] @ proj
	// dProj[k][v]  = Ln2Out[last][k] * dLogits[v]
	// dLn2Out[last][k] = sum_v proj[k][v] * dLogits[v]
	last := cache.Ln2Out[lastPos]
	flatProj  := flattenEmbedding(m.proj)
	gradsProj := make([]float64, d*m.vocabSize)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			gradsProj[k*m.vocabSize+v] = last[k] * dLogits[v]
		}
	}
	updProj := adam.proj.Step(flatProj, ClipGradient(gradsProj, 1.0))
	m.proj  = unflattenEmbedding(updProj, d, m.vocabSize)

	dLn2OutLast := make([]float64, d)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			dLn2OutLast[k] += m.proj[k][v] * dLogits[v]
		}
	}
	// dLn2Out: 마지막 위치만 non-zero
	dLn2Out := make([][]float64, seqLen)
	for i := range dLn2Out { dLn2Out[i] = make([]float64, d) }
	copy(dLn2Out[lastPos], dLn2OutLast)

	// ── 2. LN2 backward (정확) ──────────────────────────────
	// LN2 입력 = res2[i] = Ln1Out[i] + FfnOut[i]
	// dRes2 = dLn2Out → dLn1Out(ffn residual path), dFfnOut
	dRes2    := make([][]float64, seqLen)
	dLn2Scale := make([]float64, d)
	dLn2Bias  := make([]float64, d)
	for i := 0; i < seqLen; i++ {
		dx, dsc, dbs := layerNormBackward(
			dLn2Out[i], cache.Res2[i], m.ln2Scale,
			cache.Ln2Mean[i], cache.Ln2InvStd[i])
		dRes2[i] = dx
		for k := range dsc { dLn2Scale[k] += dsc[k]; dLn2Bias[k] += dbs[k] }
	}
	// residual 분기: dRes2 = d(Ln1Out + FfnOut) → 둘 다 동일
	dFfnOut      := dRes2              // FfnOut에 대한 gradient
	dLn1OutFromRes2 := copyMat(dRes2)  // Ln1Out 잔차 경로

	// ln2Scale / ln2Bias 업데이트
	updLn2Scale := adam.ln2Scale.Step(m.ln2Scale, dLn2Scale)
	updLn2Bias  := adam.ln2Bias.Step(m.ln2Bias,  dLn2Bias)
	m.ln2Scale, m.ln2Bias = updLn2Scale, updLn2Bias

	// ── 3. FFN backward ─────────────────────────────────────
	// FfnOut[i] = H[i] @ W2 + b2
	// H[i][j]   = GELU(Ln1Out[i] @ W1[:,j] + b1[j])
	flatW2    := flattenEmbedding(m.W2)
	gradsW2   := make([]float64, ffn*d)
	gradsb2   := make([]float64, d)
	dHidden   := make([][]float64, seqLen)  // dLoss/dH (FFN hidden)

	for i := 0; i < seqLen; i++ {
		dHidden[i] = make([]float64, ffn)
		for k := 0; k < d; k++ {
			gradsb2[k] += dFfnOut[i][k]
			for j := 0; j < ffn; j++ {
				gradsW2[j*d+k] += cache.H[i][j] * dFfnOut[i][k]
				dHidden[i][j]  += m.W2[j][k] * dFfnOut[i][k]
			}
		}
	}
	updW2 := adam.W2.Step(flatW2, ClipGradient(gradsW2, 1.0))
	m.W2  = unflattenEmbedding(updW2, ffn, d)
	updb2 := adam.b2.Step(m.b2, ClipGradient(gradsb2, 1.0))
	m.b2  = updb2

	// W1, b1: dHidden → dGELU(preact) → dLn1Out (FFN 경로)
	flatW1      := flattenEmbedding(m.W1)
	gradsW1     := make([]float64, d*ffn)
	gradsb1     := make([]float64, ffn)
	dLn1FromFFN := make([][]float64, seqLen)

	for i := 0; i < seqLen; i++ {
		dLn1FromFFN[i] = make([]float64, d)
		for j := 0; j < ffn; j++ {
			dg := dHidden[i][j] * geluGrad(cache.HPreact[i][j])  // 정확한 GELU 미분
			gradsb1[j] += dg
			for k := 0; k < d; k++ {
				gradsW1[k*ffn+j] += cache.Ln1Out[i][k] * dg
				dLn1FromFFN[i][k] += m.W1[k][j] * dg
			}
		}
	}
	updW1 := adam.W1.Step(flatW1, ClipGradient(gradsW1, 1.0))
	m.W1  = unflattenEmbedding(updW1, d, ffn)
	updb1 := adam.b1.Step(m.b1, ClipGradient(gradsb1, 1.0))
	m.b1  = updb1

	// dLn1Out = FFN잔차 경로 + FFN 직접 경로
	dLn1Out := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		dLn1Out[i] = make([]float64, d)
		for k := 0; k < d; k++ {
			dLn1Out[i][k] = dLn1OutFromRes2[i][k] + dLn1FromFFN[i][k]
		}
	}

	// ── 4. LN1 backward (정확) ──────────────────────────────
	// LN1 입력 = res1[i] = X[i] + MhaOut[i]
	dRes1     := make([][]float64, seqLen)
	dLn1Scale := make([]float64, d)
	dLn1Bias  := make([]float64, d)
	for i := 0; i < seqLen; i++ {
		dx, dsc, dbs := layerNormBackward(
			dLn1Out[i], cache.Res1[i], m.ln1Scale,
			cache.Ln1Mean[i], cache.Ln1InvStd[i])
		dRes1[i] = dx
		for k := range dsc { dLn1Scale[k] += dsc[k]; dLn1Bias[k] += dbs[k] }
	}
	// residual: dRes1 = d(X + MhaOut)
	dMhaOut  := copyMat(dRes1) // MhaOut에 대한 gradient
	dXFromLN1 := copyMat(dRes1) // X의 LN1 경로 gradient

	updLn1Scale := adam.ln1Scale.Step(m.ln1Scale, dLn1Scale)
	updLn1Bias  := adam.ln1Bias.Step(m.ln1Bias,  dLn1Bias)
	m.ln1Scale, m.ln1Bias = updLn1Scale, updLn1Bias

	// ── 5. Attention backward (정확) ────────────────────────
	// MhaOut = AttnOut @ Wo
	// dWo, dAttnOut

	flatWo    := flattenEmbedding(m.Wo)
	gradsWo   := make([]float64, d*d)
	dAttnOut  := make([][]float64, seqLen)
	for i := range dAttnOut { dAttnOut[i] = make([]float64, d) }

	for i := 0; i < seqLen; i++ {
		for k := 0; k < d; k++ {
			for j := 0; j < d; j++ {
				gradsWo[j*d+k] += cache.AttnOut[i][j] * dMhaOut[i][k]
				dAttnOut[i][j] += m.Wo[j][k] * dMhaOut[i][k]
			}
		}
	}
	updWo := adam.Wo.Step(flatWo, ClipGradient(gradsWo, 1.0))
	m.Wo  = unflattenEmbedding(updWo, d, d)

	// 헤드별 정확한 attention backward
	// dAttnOut[i][h*dH : (h+1)*dH] = sum_j(attnW[h][i][j] * dV[j][h*dH:])
	// dV[j][h*dH:] += sum_i(attnW[h][i][j] * dAttnOut[i][h*dH:])
	// dAttnW[h][i][j] = sum_k(dAttnOut[i][h*dH+k] * V[j][h*dH+k])
	// → softmax backward → dScore → dQ, dK

	dQ := make([][]float64, seqLen)
	dK := make([][]float64, seqLen)
	dV := make([][]float64, seqLen)
	for i := range dQ {
		dQ[i] = make([]float64, d)
		dK[i] = make([]float64, d)
		dV[i] = make([]float64, d)
	}

	attnScale := 1.0 / math.Sqrt(float64(dH))

	for h := 0; h < nH; h++ {
		hS := h * dH

		// dAttnW[h][i][j] = dot(dAttnOut[i][hS:hS+dH], V[j][hS:hS+dH])
		dAttnWh := make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			dAttnWh[i] = make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += dAttnOut[i][hS+k] * cache.V[j][hS+k]
				}
				dAttnWh[i][j] = dot
			}
		}

		// dV[j] += sum_i(attnW[h][i][j] * dAttnOut[i])
		for i := 0; i < seqLen; i++ {
			for j := 0; j <= i; j++ {
				for k := 0; k < dH; k++ {
					dV[j][hS+k] += cache.AttnWPerHead[h][i][j] * dAttnOut[i][hS+k]
				}
			}
		}

		// softmax backward: dScore[i][j] = attnW*(dAttnW - sum_k(attnW[k]*dAttnW[k]))
		// → dQ[i], dK[j]
		for i := 0; i < seqLen; i++ {
			aw := cache.AttnWPerHead[h][i]
			da := dAttnWh[i]

			// sum_k(aw[k] * da[k]) (causal: only j<=i)
			dot := 0.0
			for j := 0; j <= i; j++ { dot += aw[j] * da[j] }

			// dScore[i][j] = aw[j] * (da[j] - dot)
			for j := 0; j <= i; j++ {
				dScore := aw[j] * (da[j] - dot) * attnScale
				// dScore → dQ[i], dK[j]
				for k := 0; k < dH; k++ {
					dQ[i][hS+k] += dScore * cache.K[j][hS+k]
					dK[j][hS+k] += dScore * cache.Q[i][hS+k]
				}
			}
		}
	}

	// Wq, Wk, Wv backward: dW = X^T @ dQ/dK/dV
	flatWq  := flattenEmbedding(m.Wq)
	flatWk  := flattenEmbedding(m.Wk)
	flatWv  := flattenEmbedding(m.Wv)
	gradsWq := make([]float64, d*d)
	gradsWk := make([]float64, d*d)
	gradsWv := make([]float64, d*d)
	dXFromAttn := make([][]float64, seqLen)
	for i := range dXFromAttn { dXFromAttn[i] = make([]float64, d) }

	for i := 0; i < seqLen; i++ {
		for j := 0; j < d; j++ {
			for k := 0; k < d; k++ {
				gradsWq[j*d+k] += cache.X[i][j] * dQ[i][k]
				gradsWk[j*d+k] += cache.X[i][j] * dK[i][k]
				gradsWv[j*d+k] += cache.X[i][j] * dV[i][k]
				// dX = dQ @ Wq^T + dK @ Wk^T + dV @ Wv^T
				dXFromAttn[i][j] += m.Wq[j][k]*dQ[i][k] + m.Wk[j][k]*dK[i][k] + m.Wv[j][k]*dV[i][k]
			}
		}
	}
	updWq := adam.Wq.Step(flatWq, ClipGradient(gradsWq, 1.0))
	updWk := adam.Wk.Step(flatWk, ClipGradient(gradsWk, 1.0))
	updWv := adam.Wv.Step(flatWv, ClipGradient(gradsWv, 1.0))
	m.Wq = unflattenEmbedding(updWq, d, d)
	m.Wk = unflattenEmbedding(updWk, d, d)
	m.Wv = unflattenEmbedding(updWv, d, d)

	// ── 6. Embedding backward (모든 위치) ───────────────────
	// dX[i] = dXFromLN1[i] + dXFromAttn[i]
	// embedding[seq[i]] += dX[i]
	flatEmb  := flattenEmbedding(m.embedding)
	gradsEmb := make([]float64, m.vocabSize*d)

	for pos, tok := range seq {
		if tok >= m.vocabSize { continue }
		for k := 0; k < d; k++ {
			gradsEmb[tok*d+k] += dXFromLN1[pos][k] + dXFromAttn[pos][k]
		}
	}
	updEmb   := adam.emb.Step(flatEmb, ClipGradient(gradsEmb, 1.0))
	m.embedding = unflattenEmbedding(updEmb, m.vocabSize, d)
}

// ──────────────────────────────────────────────────────────
// Helpers
// ──────────────────────────────────────────────────────────

func copyMat(a [][]float64) [][]float64 {
	out := make([][]float64, len(a))
	for i := range a {
		out[i] = make([]float64, len(a[i]))
		copy(out[i], a[i])
	}
	return out
}

// ──────────────────────────────────────────────────────────
// Adam 묶음
// ──────────────────────────────────────────────────────────

type BPAdams struct {
	emb      *AdamState
	Wq       *AdamState
	Wk       *AdamState
	Wv       *AdamState
	Wo       *AdamState
	ln1Scale *AdamState
	ln1Bias  *AdamState
	W1       *AdamState
	b1       *AdamState
	W2       *AdamState
	b2       *AdamState
	ln2Scale *AdamState
	ln2Bias  *AdamState
	proj     *AdamState
}

func newBPAdams(lr float64, vocabSize, d, ffn int) *BPAdams {
	return &BPAdams{
		emb:      NewAdamState(lr, vocabSize*d),
		Wq:       NewAdamState(lr, d*d),
		Wk:       NewAdamState(lr, d*d),
		Wv:       NewAdamState(lr, d*d),
		Wo:       NewAdamState(lr, d*d),
		ln1Scale: NewAdamState(lr, d),
		ln1Bias:  NewAdamState(lr, d),
		W1:       NewAdamState(lr, d*ffn),
		b1:       NewAdamState(lr, ffn),
		W2:       NewAdamState(lr, ffn*d),
		b2:       NewAdamState(lr, d),
		ln2Scale: NewAdamState(lr, d),
		ln2Bias:  NewAdamState(lr, d),
		proj:     NewAdamState(lr, d*vocabSize),
	}
}

func (a *BPAdams) setLR(lr float64) {
	a.emb.LearningRate = lr
	a.Wq.LearningRate  = lr
	a.Wk.LearningRate  = lr
	a.Wv.LearningRate  = lr
	a.Wo.LearningRate  = lr
	a.ln1Scale.LearningRate = lr
	a.ln1Bias.LearningRate  = lr
	a.W1.LearningRate  = lr
	a.b1.LearningRate  = lr
	a.W2.LearningRate  = lr
	a.b2.LearningRate  = lr
	a.ln2Scale.LearningRate = lr
	a.ln2Bias.LearningRate  = lr
	a.proj.LearningRate = lr
}

// ──────────────────────────────────────────────────────────
// 학습 루프
// ──────────────────────────────────────────────────────────

func trainBP() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 7: Full Backpropagation Transformer (정확한 역전파)  ║")
	fmt.Println("║  수정: LN/Attn/Emb backward 근사 완전 제거                ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	fmt.Println("[1/5] Loading data...")
	tokens, vocab, err := tokenizeRealData("data/real_corpus_large.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}
	fmt.Printf("✅ Loaded %d tokens, vocab=%d\n\n", len(tokens), len(vocab))

	if len(tokens) < 64 {
		fmt.Println("⚠️  데이터 너무 적음 — data/corpus.txt 사용")
		tokens, vocab, err = tokenizeRealData("data/corpus.txt")
		if err != nil {
			fmt.Printf("❌ corpus.txt: %v\n", err)
			return
		}
		fmt.Printf("✅ corpus.txt: %d tokens, vocab=%d\n\n", len(tokens), len(vocab))
	}

	d       := 128
	ffn     := 512
	numHeads := 4

	fmt.Println("[2/5] Creating BP Transformer...")
	model := newBPModel(len(vocab), d, ffn, numHeads)
	paramCount := len(vocab)*d + d*d*4 + d*ffn*2 + d*len(vocab)
	fmt.Printf("✅ d=%d, heads=%d, FFN=%d, params=~%dk\n\n", d, numHeads, ffn, paramCount/1000)

	fmt.Println("[3/5] Initializing Adam (14 instances)...")
	adam := newBPAdams(0.0003, len(vocab), d, ffn)
	fmt.Printf("✅ Adam ready (lr=0.0003, β1=0.9, β2=0.999)\n\n")

	seqLen      := 32
	epochs      := 10
	numBatches  := 300
	warmupSteps := 200
	totalSteps  := epochs * numBatches

	fmt.Println("[4/5] Training config:")
	fmt.Printf("   seqLen=%d, epochs=%d, batches/epoch=%d\n", seqLen, epochs, numBatches)
	fmt.Printf("   warmup=%d steps, cosine decay\n\n", warmupSteps)

	fmt.Println("[5/5] Training...")
	fmt.Println("══════════════════════════════════════════════════════════════")

	losses  := make([]float64, 0, epochs)
	bestPPL := math.MaxFloat64

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < numBatches; batch++ {
			startIdx := rand.Intn(len(tokens) - seqLen - 1)
			seq       := tokens[startIdx : startIdx+seqLen]
			targetTok := tokens[startIdx+seqLen]

			logits, cache := model.forwardBP(seq)
			probs := softmax1D(logits)

			loss := math.Log(float64(len(vocab))) // fallback
			if targetTok < len(probs) && probs[targetTok] > 1e-10 {
				loss = -math.Log(probs[targetTok])
			}
			epochLoss += loss

			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if targetTok < len(dLogits) { dLogits[targetTok] -= 1.0 }

			// LR schedule: warmup + cosine
			step := (epoch-1)*numBatches + batch + 1
			var lr float64
			if step < warmupSteps {
				lr = 0.0003 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0003 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adam.setLR(lr)

			model.backwardStep(seq, targetTok, cache, dLogits, adam)

			if batch%100 == 0 {
				avg := epochLoss / float64(batch+1)
				fmt.Printf("Epoch %02d/%d  batch %3d/%d  loss=%.4f  ppl=%.1f  lr=%.5f\r",
					epoch, epochs, batch+1, numBatches, avg, math.Exp(avg), lr)
			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses  = append(losses, avgLoss)
		ppl     := math.Exp(avgLoss)
		marker  := ""
		if ppl < bestPPL {
			bestPPL = ppl
			marker  = " ★ best"
		}
		fmt.Printf("\n✅ Epoch %02d: loss=%.4f  PPL=%.2f%s\n", epoch, avgLoss, ppl, marker)
	}

	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("📊 학습 곡선:")
	for i, l := range losses {
		bar := ""
		if len(losses) > 1 && losses[0] > l {
			n := int((losses[0]-l)/losses[0]*40)
			for j := 0; j < n; j++ { bar += "█" }
		}
		fmt.Printf("  Epoch %02d: %s %.4f (PPL: %.2f)\n", i+1, bar, l, math.Exp(l))
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp  := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Phase 7 결과:\n")
		fmt.Printf("   Initial PPL: %.2f\n", iPPL)
		fmt.Printf("   Final PPL:   %.2f\n", fPPL)
		fmt.Printf("   Best PPL:    %.2f ★\n", bestPPL)
		if imp > 0 {
			fmt.Printf("   개선:        %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   악화:        %.1f%% ⚠️\n\n", -imp)
		}
	}
}

package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// Phase 7: Full Backpropagation Transformer
// 정확한 역전파: 근사 없음
//
// 수정 사항 (vs 구 버전):
//   - BlockCache: LN1/LN2 통계(mean, invStd) + residual 입력 저장
//   - LN backward: 정확한 수식 (근사 제거)
//   - Attention backward: 정확한 Q/K score gradient
//     softmax backward → dScore → dQ, dK (chain rule 완전)
//   - Embedding backward: seq 모든 위치 업데이트 (target만 아님)
//   - per-head 분리 forward/backward (헤드 평균 attnW → 헤드별 정확한 grad)
// ==================================================

// BlockCache Forward 시 중간 활성화 캐시
type BlockCache struct {
	X        [][]float64 // 블록 입력 [seqLen, d]  (embedding 출력)
	Q        [][]float64 // [seqLen, d]
	K        [][]float64 // [seqLen, d]
	V        [][]float64 // [seqLen, d]

	// 헤드별 attention weights [numHeads][seqLen][seqLen]
	AttnWPerHead [][][]float64

	AttnOut  [][]float64 // [seqLen, d]  softmax(QK^T/sqrt(dh)) @ V  concat
	MhaOut   [][]float64 // [seqLen, d]  AttnOut @ Wo

	// LN1: Add&Norm(X + MhaOut)
	Res1     [][]float64 // [seqLen, d]  X + MhaOut  (LN 입력)
	Ln1Mean  []float64   // [seqLen]
	Ln1InvStd []float64  // [seqLen]
	Ln1Out   [][]float64 // [seqLen, d]

	H        [][]float64 // FFN hidden [seqLen, ffn]  (post-GELU)
	HPreact  [][]float64 // FFN hidden pre-GELU [seqLen, ffn]
	FfnOut   [][]float64 // [seqLen, d]

	// LN2: Add&Norm(Ln1Out + FfnOut)
	Res2      [][]float64 // [seqLen, d]
	Ln2Mean   []float64   // [seqLen]
	Ln2InvStd []float64   // [seqLen]
	Ln2Out    [][]float64 // [seqLen, d]
}

// BPModel Full backprop Transformer (1-layer)
type BPModel struct {
	vocabSize int
	dModel    int
	dFFn      int
	numHeads  int
	dHead     int

	embedding [][]float64 // [vocab, d]
	Wq        [][]float64 // [d, d]
	Wk        [][]float64
	Wv        [][]float64
	Wo        [][]float64
	ln1Scale  []float64
	ln1Bias   []float64
	W1        [][]float64 // [d, ffn]
	b1        []float64
	W2        [][]float64 // [ffn, d]
	b2        []float64
	ln2Scale  []float64
	ln2Bias   []float64
	proj      [][]float64 // [d, vocab]
}

func newBPModel(vocabSize, d, ffn, numHeads int) *BPModel {
	scale  := math.Sqrt(2.0 / float64(d+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))
	vScale := math.Sqrt(2.0 / float64(vocabSize+d))
	return &BPModel{
		vocabSize: vocabSize,
		dModel:    d,
		dFFn:      ffn,
		numHeads:  numHeads,
		dHead:     d / numHeads,
		embedding: make2DRand(vocabSize, d, vScale),
		Wq:        make2DRand(d, d, scale),
		Wk:        make2DRand(d, d, scale),
		Wv:        make2DRand(d, d, scale),
		Wo:        make2DRand(d, d, scale),
		ln1Scale:  onesVec(d),
		ln1Bias:   zerosVec(d),
		W1:        make2DRand(d, ffn, fScale),
		b1:        zerosVec(ffn),
		W2:        make2DRand(ffn, d, fScale),
		b2:        zerosVec(d),
		ln2Scale:  onesVec(d),
		ln2Bias:   zerosVec(d),
		proj:      make2DRand(d, vocabSize, vScale),
	}
}

// ──────────────────────────────────────────────────────────
// LayerNorm helpers
// ──────────────────────────────────────────────────────────

func layerNormFull(x, scale, bias []float64) (out []float64, mean, invStd float64) {
	n := len(x)
	for _, v := range x { mean += v }
	mean /= float64(n)
	variance := 0.0
	for _, v := range x {
		d := v - mean
		variance += d * d
	}
	variance /= float64(n)
	invStd = 1.0 / math.Sqrt(variance+1e-5)
	out = make([]float64, n)
	for i, v := range x {
		out[i] = scale[i]*(v-mean)*invStd + bias[i]
	}
	return
}

// layerNormBackward: 정확한 수식
// dX = invStd/n * (n*dOut*scale - sum(dOut*scale) - xHat*sum(dOut*scale*xHat))
func layerNormBackward(dOut, x, scale []float64, mean, invStd float64) (dX, dScale, dBias []float64) {
	n := len(dOut)
	dScale = make([]float64, n)
	dBias  = make([]float64, n)
	dX     = make([]float64, n)

	xHat := make([]float64, n)
	for i := range x { xHat[i] = (x[i] - mean) * invStd }

	sumDS, sumDSX := 0.0, 0.0
	for i := range dOut {
		dScale[i] = dOut[i] * xHat[i]
		dBias[i]  = dOut[i]
		sumDS  += dOut[i] * scale[i]
		sumDSX += dOut[i] * scale[i] * xHat[i]
	}
	for i := range dOut {
		dX[i] = invStd / float64(n) * (float64(n)*dOut[i]*scale[i] - sumDS - xHat[i]*sumDSX)
	}
	return
}

// ──────────────────────────────────────────────────────────
// GELU & derivative
// ──────────────────────────────────────────────────────────

// geluGrad: dGELU/dx 정확한 수식
func geluGrad(x float64) float64 {
	c := math.Sqrt(2.0 / math.Pi)
	inner := c * (x + 0.044715*x*x*x)
	tanh  := math.Tanh(inner)
	dInner := c * (1.0 + 3*0.044715*x*x)
	return 0.5*(1+tanh) + 0.5*x*(1-tanh*tanh)*dInner
}

// ──────────────────────────────────────────────────────────
// Forward Pass
// ──────────────────────────────────────────────────────────

func (m *BPModel) forwardBP(seq []int) (logits []float64, cache *BlockCache) {
	seqLen := len(seq)
	d  := m.dModel
	nH := m.numHeads
	dH := m.dHead

	cache = &BlockCache{}

	// Embedding
	X := make([][]float64, seqLen)
	for i, tok := range seq {
		X[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(X[i], m.embedding[tok])
		}
	}
	cache.X = copyMat(X)

	// Linear projections
	cache.Q = matmul2D(X, m.Wq) // [seqLen, d]
	cache.K = matmul2D(X, m.Wk)
	cache.V = matmul2D(X, m.Wv)

	// Multi-head causal attention (헤드별 저장)
	attnOut := make([][]float64, seqLen)
	for i := range attnOut { attnOut[i] = make([]float64, d) }

	cache.AttnWPerHead = make([][][]float64, nH)
	for h := 0; h < nH; h++ {
		hS := h * dH
		cache.AttnWPerHead[h] = make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			cache.AttnWPerHead[h][i] = make([]float64, seqLen)
		}
		scale := 1.0 / math.Sqrt(float64(dH))
		for i := 0; i < seqLen; i++ {
			scores := make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += cache.Q[i][hS+k] * cache.K[j][hS+k]
				}
				scores[j] = dot * scale
			}
			for j := i + 1; j < seqLen; j++ { scores[j] = -1e9 }
			probs := softmax1D(scores)
			copy(cache.AttnWPerHead[h][i], probs)
			for j := 0; j < seqLen; j++ {
				for k := 0; k < dH; k++ {
					attnOut[i][hS+k] += probs[j] * cache.V[j][hS+k]
				}
			}
		}
	}
	cache.AttnOut = attnOut

	// Wo
	cache.MhaOut = matmul2D(attnOut, m.Wo)

	// Add & LN1
	res1 := make([][]float64, seqLen)
	for i := range res1 { res1[i] = addResidual(X[i], cache.MhaOut[i]) }
	cache.Res1     = res1
	cache.Ln1Mean  = make([]float64, seqLen)
	cache.Ln1InvStd = make([]float64, seqLen)
	cache.Ln1Out   = make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		cache.Ln1Out[i], cache.Ln1Mean[i], cache.Ln1InvStd[i] =
			layerNormFull(res1[i], m.ln1Scale, m.ln1Bias)
	}

	// FFN
	H       := make([][]float64, seqLen)
	HPreact := make([][]float64, seqLen)
	ffnOut  := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		pre := make([]float64, m.dFFn)
		h   := make([]float64, m.dFFn)
		for j := 0; j < m.dFFn; j++ {
			s := m.b1[j]
			for k := 0; k < d; k++ { s += cache.Ln1Out[i][k] * m.W1[k][j] }
			pre[j] = s
			h[j]   = geluActivation(s)
		}
		HPreact[i] = pre
		H[i]       = h
		out := make([]float64, d)
		for k := 0; k < d; k++ {
			s := m.b2[k]
			for j := 0; j < m.dFFn; j++ { s += h[j] * m.W2[j][k] }
			out[k] = s
		}
		ffnOut[i] = out
	}
	cache.H       = H
	cache.HPreact = HPreact
	cache.FfnOut  = ffnOut

	// Add & LN2
	res2 := make([][]float64, seqLen)
	for i := range res2 { res2[i] = addResidual(cache.Ln1Out[i], ffnOut[i]) }
	cache.Res2     = res2
	cache.Ln2Mean  = make([]float64, seqLen)
	cache.Ln2InvStd = make([]float64, seqLen)
	cache.Ln2Out   = make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		cache.Ln2Out[i], cache.Ln2Mean[i], cache.Ln2InvStd[i] =
			layerNormFull(res2[i], m.ln2Scale, m.ln2Bias)
	}

	// Logits (마지막 위치)
	last := cache.Ln2Out[seqLen-1]
	logits = make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		s := 0.0
		for k := 0; k < d; k++ { s += last[k] * m.proj[k][v] }
		logits[v] = s
	}
	return
}

// ──────────────────────────────────────────────────────────
// Backward Pass — 정확한 gradient, 근사 없음
// ──────────────────────────────────────────────────────────

func (m *BPModel) backwardStep(
	seq []int,
	targetTok int,
	cache *BlockCache,
	dLogits []float64,
	adam *BPAdams,
) {
	d       := m.dModel
	ffn     := m.dFFn
	seqLen  := len(seq)
	lastPos := seqLen - 1
	nH      := m.numHeads
	dH      := m.dHead

	// ── 1. proj backward ────────────────────────────────────
	// logits = Ln2Out[last] @ proj
	// dProj[k][v]  = Ln2Out[last][k] * dLogits[v]
	// dLn2Out[last][k] = sum_v proj[k][v] * dLogits[v]
	last := cache.Ln2Out[lastPos]
	flatProj  := flattenEmbedding(m.proj)
	gradsProj := make([]float64, d*m.vocabSize)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			gradsProj[k*m.vocabSize+v] = last[k] * dLogits[v]
		}
	}
	updProj := adam.proj.Step(flatProj, ClipGradient(gradsProj, 1.0))
	m.proj  = unflattenEmbedding(updProj, d, m.vocabSize)

	dLn2OutLast := make([]float64, d)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			dLn2OutLast[k] += m.proj[k][v] * dLogits[v]
		}
	}
	// dLn2Out: 마지막 위치만 non-zero
	dLn2Out := make([][]float64, seqLen)
	for i := range dLn2Out { dLn2Out[i] = make([]float64, d) }
	copy(dLn2Out[lastPos], dLn2OutLast)

	// ── 2. LN2 backward (정확) ──────────────────────────────
	// LN2 입력 = res2[i] = Ln1Out[i] + FfnOut[i]
	// dRes2 = dLn2Out → dLn1Out(ffn residual path), dFfnOut
	dRes2    := make([][]float64, seqLen)
	dLn2Scale := make([]float64, d)
	dLn2Bias  := make([]float64, d)
	for i := 0; i < seqLen; i++ {
		dx, dsc, dbs := layerNormBackward(
			dLn2Out[i], cache.Res2[i], m.ln2Scale,
			cache.Ln2Mean[i], cache.Ln2InvStd[i])
		dRes2[i] = dx
		for k := range dsc { dLn2Scale[k] += dsc[k]; dLn2Bias[k] += dbs[k] }
	}
	// residual 분기: dRes2 = d(Ln1Out + FfnOut) → 둘 다 동일
	dFfnOut      := dRes2              // FfnOut에 대한 gradient
	dLn1OutFromRes2 := copyMat(dRes2)  // Ln1Out 잔차 경로

	// ln2Scale / ln2Bias 업데이트
	updLn2Scale := adam.ln2Scale.Step(m.ln2Scale, dLn2Scale)
	updLn2Bias  := adam.ln2Bias.Step(m.ln2Bias,  dLn2Bias)
	m.ln2Scale, m.ln2Bias = updLn2Scale, updLn2Bias

	// ── 3. FFN backward ─────────────────────────────────────
	// FfnOut[i] = H[i] @ W2 + b2
	// H[i][j]   = GELU(Ln1Out[i] @ W1[:,j] + b1[j])
	flatW2    := flattenEmbedding(m.W2)
	gradsW2   := make([]float64, ffn*d)
	gradsb2   := make([]float64, d)
	dHidden   := make([][]float64, seqLen)  // dLoss/dH (FFN hidden)

	for i := 0; i < seqLen; i++ {
		dHidden[i] = make([]float64, ffn)
		for k := 0; k < d; k++ {
			gradsb2[k] += dFfnOut[i][k]
			for j := 0; j < ffn; j++ {
				gradsW2[j*d+k] += cache.H[i][j] * dFfnOut[i][k]
				dHidden[i][j]  += m.W2[j][k] * dFfnOut[i][k]
			}
		}
	}
	updW2 := adam.W2.Step(flatW2, ClipGradient(gradsW2, 1.0))
	m.W2  = unflattenEmbedding(updW2, ffn, d)
	updb2 := adam.b2.Step(m.b2, ClipGradient(gradsb2, 1.0))
	m.b2  = updb2

	// W1, b1: dHidden → dGELU(preact) → dLn1Out (FFN 경로)
	flatW1      := flattenEmbedding(m.W1)
	gradsW1     := make([]float64, d*ffn)
	gradsb1     := make([]float64, ffn)
	dLn1FromFFN := make([][]float64, seqLen)

	for i := 0; i < seqLen; i++ {
		dLn1FromFFN[i] = make([]float64, d)
		for j := 0; j < ffn; j++ {
			dg := dHidden[i][j] * geluGrad(cache.HPreact[i][j])  // 정확한 GELU 미분
			gradsb1[j] += dg
			for k := 0; k < d; k++ {
				gradsW1[k*ffn+j] += cache.Ln1Out[i][k] * dg
				dLn1FromFFN[i][k] += m.W1[k][j] * dg
			}
		}
	}
	updW1 := adam.W1.Step(flatW1, ClipGradient(gradsW1, 1.0))
	m.W1  = unflattenEmbedding(updW1, d, ffn)
	updb1 := adam.b1.Step(m.b1, ClipGradient(gradsb1, 1.0))
	m.b1  = updb1

	// dLn1Out = FFN잔차 경로 + FFN 직접 경로
	dLn1Out := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		dLn1Out[i] = make([]float64, d)
		for k := 0; k < d; k++ {
			dLn1Out[i][k] = dLn1OutFromRes2[i][k] + dLn1FromFFN[i][k]
		}
	}

	// ── 4. LN1 backward (정확) ──────────────────────────────
	// LN1 입력 = res1[i] = X[i] + MhaOut[i]
	dRes1     := make([][]float64, seqLen)
	dLn1Scale := make([]float64, d)
	dLn1Bias  := make([]float64, d)
	for i := 0; i < seqLen; i++ {
		dx, dsc, dbs := layerNormBackward(
			dLn1Out[i], cache.Res1[i], m.ln1Scale,
			cache.Ln1Mean[i], cache.Ln1InvStd[i])
		dRes1[i] = dx
		for k := range dsc { dLn1Scale[k] += dsc[k]; dLn1Bias[k] += dbs[k] }
	}
	// residual: dRes1 = d(X + MhaOut)
	dMhaOut  := copyMat(dRes1) // MhaOut에 대한 gradient
	dXFromLN1 := copyMat(dRes1) // X의 LN1 경로 gradient

	updLn1Scale := adam.ln1Scale.Step(m.ln1Scale, dLn1Scale)
	updLn1Bias  := adam.ln1Bias.Step(m.ln1Bias,  dLn1Bias)
	m.ln1Scale, m.ln1Bias = updLn1Scale, updLn1Bias

	// ── 5. Attention backward (정확) ────────────────────────
	// MhaOut = AttnOut @ Wo
	// dWo, dAttnOut

	flatWo    := flattenEmbedding(m.Wo)
	gradsWo   := make([]float64, d*d)
	dAttnOut  := make([][]float64, seqLen)
	for i := range dAttnOut { dAttnOut[i] = make([]float64, d) }

	for i := 0; i < seqLen; i++ {
		for k := 0; k < d; k++ {
			for j := 0; j < d; j++ {
				gradsWo[j*d+k] += cache.AttnOut[i][j] * dMhaOut[i][k]
				dAttnOut[i][j] += m.Wo[j][k] * dMhaOut[i][k]
			}
		}
	}
	updWo := adam.Wo.Step(flatWo, ClipGradient(gradsWo, 1.0))
	m.Wo  = unflattenEmbedding(updWo, d, d)

	// 헤드별 정확한 attention backward
	// dAttnOut[i][h*dH : (h+1)*dH] = sum_j(attnW[h][i][j] * dV[j][h*dH:])
	// dV[j][h*dH:] += sum_i(attnW[h][i][j] * dAttnOut[i][h*dH:])
	// dAttnW[h][i][j] = sum_k(dAttnOut[i][h*dH+k] * V[j][h*dH+k])
	// → softmax backward → dScore → dQ, dK

	dQ := make([][]float64, seqLen)
	dK := make([][]float64, seqLen)
	dV := make([][]float64, seqLen)
	for i := range dQ {
		dQ[i] = make([]float64, d)
		dK[i] = make([]float64, d)
		dV[i] = make([]float64, d)
	}

	attnScale := 1.0 / math.Sqrt(float64(dH))

	for h := 0; h < nH; h++ {
		hS := h * dH

		// dAttnW[h][i][j] = dot(dAttnOut[i][hS:hS+dH], V[j][hS:hS+dH])
		dAttnWh := make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			dAttnWh[i] = make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += dAttnOut[i][hS+k] * cache.V[j][hS+k]
				}
				dAttnWh[i][j] = dot
			}
		}

		// dV[j] += sum_i(attnW[h][i][j] * dAttnOut[i])
		for i := 0; i < seqLen; i++ {
			for j := 0; j <= i; j++ {
				for k := 0; k < dH; k++ {
					dV[j][hS+k] += cache.AttnWPerHead[h][i][j] * dAttnOut[i][hS+k]
				}
			}
		}

		// softmax backward: dScore[i][j] = attnW*(dAttnW - sum_k(attnW[k]*dAttnW[k]))
		// → dQ[i], dK[j]
		for i := 0; i < seqLen; i++ {
			aw := cache.AttnWPerHead[h][i]
			da := dAttnWh[i]

			// sum_k(aw[k] * da[k]) (causal: only j<=i)
			dot := 0.0
			for j := 0; j <= i; j++ { dot += aw[j] * da[j] }

			// dScore[i][j] = aw[j] * (da[j] - dot)
			for j := 0; j <= i; j++ {
				dScore := aw[j] * (da[j] - dot) * attnScale
				// dScore → dQ[i], dK[j]
				for k := 0; k < dH; k++ {
					dQ[i][hS+k] += dScore * cache.K[j][hS+k]
					dK[j][hS+k] += dScore * cache.Q[i][hS+k]
				}
			}
		}
	}

	// Wq, Wk, Wv backward: dW = X^T @ dQ/dK/dV
	flatWq  := flattenEmbedding(m.Wq)
	flatWk  := flattenEmbedding(m.Wk)
	flatWv  := flattenEmbedding(m.Wv)
	gradsWq := make([]float64, d*d)
	gradsWk := make([]float64, d*d)
	gradsWv := make([]float64, d*d)
	dXFromAttn := make([][]float64, seqLen)
	for i := range dXFromAttn { dXFromAttn[i] = make([]float64, d) }

	for i := 0; i < seqLen; i++ {
		for j := 0; j < d; j++ {
			for k := 0; k < d; k++ {
				gradsWq[j*d+k] += cache.X[i][j] * dQ[i][k]
				gradsWk[j*d+k] += cache.X[i][j] * dK[i][k]
				gradsWv[j*d+k] += cache.X[i][j] * dV[i][k]
				// dX = dQ @ Wq^T + dK @ Wk^T + dV @ Wv^T
				dXFromAttn[i][j] += m.Wq[j][k]*dQ[i][k] + m.Wk[j][k]*dK[i][k] + m.Wv[j][k]*dV[i][k]
			}
		}
	}
	updWq := adam.Wq.Step(flatWq, ClipGradient(gradsWq, 1.0))
	updWk := adam.Wk.Step(flatWk, ClipGradient(gradsWk, 1.0))
	updWv := adam.Wv.Step(flatWv, ClipGradient(gradsWv, 1.0))
	m.Wq = unflattenEmbedding(updWq, d, d)
	m.Wk = unflattenEmbedding(updWk, d, d)
	m.Wv = unflattenEmbedding(updWv, d, d)

	// ── 6. Embedding backward (모든 위치) ───────────────────
	// dX[i] = dXFromLN1[i] + dXFromAttn[i]
	// embedding[seq[i]] += dX[i]
	flatEmb  := flattenEmbedding(m.embedding)
	gradsEmb := make([]float64, m.vocabSize*d)

	for pos, tok := range seq {
		if tok >= m.vocabSize { continue }
		for k := 0; k < d; k++ {
			gradsEmb[tok*d+k] += dXFromLN1[pos][k] + dXFromAttn[pos][k]
		}
	}
	updEmb   := adam.emb.Step(flatEmb, ClipGradient(gradsEmb, 1.0))
	m.embedding = unflattenEmbedding(updEmb, m.vocabSize, d)
}

// ──────────────────────────────────────────────────────────
// Helpers
// ──────────────────────────────────────────────────────────

func copyMat(a [][]float64) [][]float64 {
	out := make([][]float64, len(a))
	for i := range a {
		out[i] = make([]float64, len(a[i]))
		copy(out[i], a[i])
	}
	return out
}

// ──────────────────────────────────────────────────────────
// Adam 묶음
// ──────────────────────────────────────────────────────────

type BPAdams struct {
	emb      *AdamState
	Wq       *AdamState
	Wk       *AdamState
	Wv       *AdamState
	Wo       *AdamState
	ln1Scale *AdamState
	ln1Bias  *AdamState
	W1       *AdamState
	b1       *AdamState
	W2       *AdamState
	b2       *AdamState
	ln2Scale *AdamState
	ln2Bias  *AdamState
	proj     *AdamState
}

func newBPAdams(lr float64, vocabSize, d, ffn int) *BPAdams {
	return &BPAdams{
		emb:      NewAdamState(lr, vocabSize*d),
		Wq:       NewAdamState(lr, d*d),
		Wk:       NewAdamState(lr, d*d),
		Wv:       NewAdamState(lr, d*d),
		Wo:       NewAdamState(lr, d*d),
		ln1Scale: NewAdamState(lr, d),
		ln1Bias:  NewAdamState(lr, d),
		W1:       NewAdamState(lr, d*ffn),
		b1:       NewAdamState(lr, ffn),
		W2:       NewAdamState(lr, ffn*d),
		b2:       NewAdamState(lr, d),
		ln2Scale: NewAdamState(lr, d),
		ln2Bias:  NewAdamState(lr, d),
		proj:     NewAdamState(lr, d*vocabSize),
	}
}

func (a *BPAdams) setLR(lr float64) {
	a.emb.LearningRate = lr
	a.Wq.LearningRate  = lr
	a.Wk.LearningRate  = lr
	a.Wv.LearningRate  = lr
	a.Wo.LearningRate  = lr
	a.ln1Scale.LearningRate = lr
	a.ln1Bias.LearningRate  = lr
	a.W1.LearningRate  = lr
	a.b1.LearningRate  = lr
	a.W2.LearningRate  = lr
	a.b2.LearningRate  = lr
	a.ln2Scale.LearningRate = lr
	a.ln2Bias.LearningRate  = lr
	a.proj.LearningRate = lr
}

// ──────────────────────────────────────────────────────────
// 학습 루프
// ──────────────────────────────────────────────────────────

func trainBP() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 7: Full Backpropagation Transformer (정확한 역전파)  ║")
	fmt.Println("║  수정: LN/Attn/Emb backward 근사 완전 제거                ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	fmt.Println("[1/5] Loading data...")
	tokens, vocab, err := tokenizeRealData("data/real_corpus_large.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}
	fmt.Printf("✅ Loaded %d tokens, vocab=%d\n\n", len(tokens), len(vocab))

	if len(tokens) < 64 {
		fmt.Println("⚠️  데이터 너무 적음 — data/corpus.txt 사용")
		tokens, vocab, err = tokenizeRealData("data/corpus.txt")
		if err != nil {
			fmt.Printf("❌ corpus.txt: %v\n", err)
			return
		}
		fmt.Printf("✅ corpus.txt: %d tokens, vocab=%d\n\n", len(tokens), len(vocab))
	}

	d        := 64
	ffn      := 256
	numHeads := 4

	fmt.Println("[2/5] Creating BP Transformer...")
	model := newBPModel(len(vocab), d, ffn, numHeads)
	paramCount := len(vocab)*d + d*d*4 + d*ffn*2 + d*len(vocab)
	fmt.Printf("✅ d=%d, heads=%d, FFN=%d, params=~%dk\n\n", d, numHeads, ffn, paramCount/1000)

	fmt.Println("[3/5] Initializing Adam (14 instances)...")
	adam := newBPAdams(0.0003, len(vocab), d, ffn)
	fmt.Printf("✅ Adam ready (lr=0.0003, β1=0.9, β2=0.999)\n\n")

	seqLen      := 32
	epochs      := 10
	numBatches  := 300
	warmupSteps := 200
	totalSteps  := epochs * numBatches

	fmt.Println("[4/5] Training config:")
	fmt.Printf("   seqLen=%d, epochs=%d, batches/epoch=%d\n", seqLen, epochs, numBatches)
	fmt.Printf("   warmup=%d steps, cosine decay\n\n", warmupSteps)

	fmt.Println("[5/5] Training...")
	fmt.Println("══════════════════════════════════════════════════════════════")

	losses  := make([]float64, 0, epochs)
	bestPPL := math.MaxFloat64

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < numBatches; batch++ {
			startIdx := rand.Intn(len(tokens) - seqLen - 1)
			seq       := tokens[startIdx : startIdx+seqLen]
			targetTok := tokens[startIdx+seqLen]

			logits, cache := model.forwardBP(seq)
			probs := softmax1D(logits)

			loss := math.Log(float64(len(vocab))) // fallback
			if targetTok < len(probs) && probs[targetTok] > 1e-10 {
				loss = -math.Log(probs[targetTok])
			}
			epochLoss += loss

			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if targetTok < len(dLogits) { dLogits[targetTok] -= 1.0 }

			// LR schedule: warmup + cosine
			step := (epoch-1)*numBatches + batch + 1
			var lr float64
			if step < warmupSteps {
				lr = 0.0003 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0003 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adam.setLR(lr)

			model.backwardStep(seq, targetTok, cache, dLogits, adam)

			if batch%100 == 0 {
				avg := epochLoss / float64(batch+1)
				fmt.Printf("Epoch %02d/%d  batch %3d/%d  loss=%.4f  ppl=%.1f  lr=%.5f\r",
					epoch, epochs, batch+1, numBatches, avg, math.Exp(avg), lr)
			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses  = append(losses, avgLoss)
		ppl     := math.Exp(avgLoss)
		marker  := ""
		if ppl < bestPPL {
			bestPPL = ppl
			marker  = " ★ best"
		}
		fmt.Printf("\n✅ Epoch %02d: loss=%.4f  PPL=%.2f%s\n", epoch, avgLoss, ppl, marker)
	}

	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("📊 학습 곡선:")
	for i, l := range losses {
		bar := ""
		if len(losses) > 1 && losses[0] > l {
			n := int((losses[0]-l)/losses[0]*40)
			for j := 0; j < n; j++ { bar += "█" }
		}
		fmt.Printf("  Epoch %02d: %s %.4f (PPL: %.2f)\n", i+1, bar, l, math.Exp(l))
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp  := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Phase 7 결과:\n")
		fmt.Printf("   Initial PPL: %.2f\n", iPPL)
		fmt.Printf("   Final PPL:   %.2f\n", fPPL)
		fmt.Printf("   Best PPL:    %.2f ★\n", bestPPL)
		if imp > 0 {
			fmt.Printf("   개선:        %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   악화:        %.1f%% ⚠️\n\n", -imp)
		}
	}
}

