package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

// loadCorpus: corpus.txt에서 maxChars 문자만 읽어 토크나이즈
// 빈도 상위 maxVocab 문자만 vocab에 포함 (나머지 → <UNK>=0)
func loadCorpus(path string, maxChars, maxVocab int) (tokens []int, vocab map[string]int, err error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, nil, err
	}
	defer f.Close()

	buf := make([]byte, maxChars)
	n, err := io.ReadAtLeast(f, buf, 1)
	if err != nil && err != io.ErrUnexpectedEOF {
		return nil, nil, err
	}
	text := string(buf[:n])
	fmt.Printf("✅ 읽기: %d 문자 (요청 %d)\n", len([]rune(text)), maxChars)

	// 1. 문자 빈도 계산
	freq := map[rune]int{}
	for _, ch := range text {
		freq[ch]++
	}

	// 2. 빈도 내림차순 정렬 → 상위 maxVocab개 선택
	type cf struct {
		ch  rune
		cnt int
	}
	ranked := make([]cf, 0, len(freq))
	for ch, cnt := range freq {
		ranked = append(ranked, cf{ch, cnt})
	}
	sort.Slice(ranked, func(i, j int) bool { return ranked[i].cnt > ranked[j].cnt })

	vocab = map[string]int{}
	vocab["<UNK>"] = 0
	for i, r := range ranked {
		if i >= maxVocab-1 {
			break
		}
		vocab[string(r.ch)] = i + 1
	}

	// 3. 토크나이즈
	tokens = make([]int, 0, len(text))
	for _, ch := range text {
		if id, ok := vocab[string(ch)]; ok {
			tokens = append(tokens, id)
		} else {
			tokens = append(tokens, 0) // <UNK>
		}
	}

	unkCount := 0
	for _, t := range tokens {
		if t == 0 {
			unkCount++
		}
	}
	unkRatio := float64(unkCount) / float64(len(tokens)) * 100

	fmt.Printf("✅ vocab=%d (상위 %d자), tokens=%d, UNK=%.1f%%\n",
		len(vocab), maxVocab, len(tokens), unkRatio)
	return tokens, vocab, nil
}

