			fmt.Printf("│  [%-32s] %s\n", c.name, clean)
		}
		fmt.Println("└──────────────────────────────────────────────────────────")
		fmt.Println()
	}

	// Top-1 확률 분포 분석
	fmt.Println("📊 다음 토큰 확률 분포 (프롬프트: \"fn \"):")
	sample := stringToTokens("fn ", vocab)
	if len(sample) > 0 {
		logits, _ := model.forwardBP(sample)
		probs := applyTemperature(logits, 1.0)
		showTopTokens(probs, vocab, 10)
	}
}

// cleanOutput: 제어문자 제거 + 길이 제한
func cleanOutput(s string, maxLen int) string {
	var sb strings.Builder
	count := 0
	for _, ch := range s {
		if count >= maxLen {
			sb.WriteString("...")
			break
		}
		// 가시 가능한 문자만 출력
		if ch == '\n' {
			sb.WriteString("↵")
		} else if ch == '\t' {
			sb.WriteString("→")
		} else if ch >= 32 {
			sb.WriteRune(ch)
		}
		count++
	}
	return sb.String()
}

// showTopTokens: 다음 토큰 상위 N개 확률 표시
func showTopTokens(probs []float64, vocab map[string]int, n int) {
	rev := make(map[int]string, len(vocab))
	for ch, id := range vocab {
		rev[id] = ch
	}

	type tv struct{ idx int; p float64 }
	all := make([]tv, len(probs))
	for i, p := range probs { all[i] = tv{i, p} }
	sort.Slice(all, func(i, j int) bool { return all[i].p > all[j].p })

	entropy := 0.0
	for _, p := range probs {
		if p > 1e-10 {
			entropy -= p * math.Log2(p)
		}
	}

	fmt.Printf("  엔트로피: %.2f bits (최대 %.2f bits)\n", entropy, math.Log2(float64(len(probs))))
	fmt.Println("  순위  토큰      확률")
	fmt.Println("  ────  ────────  ──────")
	for i := 0; i < n && i < len(all); i++ {
		ch := rev[all[i].idx]
		if ch == "\n" { ch = "\\n" }
		if ch == "\t" { ch = "\\t" }
		if ch == " "  { ch = "·" }
		bar := strings.Repeat("█", int(all[i].p*40))
		fmt.Printf("  %3d.  %-8s  %.4f  %s\n", i+1, ch, all[i].p, bar)
	}
	fmt.Println()
}

