package main

import (
	"fmt"
	"math"
	"math/rand"
	"sort"
	"strings"
)

// ==================================================
// Mission 1: Inference — BPModel 텍스트 생성
//
// 샘플링 전략:
//   Greedy    : argmax (결정적, 반복 위험)
//   Top-K     : 상위 K개 후보에서 확률 샘플링
//   Nucleus   : 누적 확률 P(top-p) 이내 후보에서 샘플링
//   Temperature : softmax 분포 sharpening/smoothing
// ==================================================

// ─────────────────────────────────────────────────
// 샘플링 헬퍼
// ─────────────────────────────────────────────────

// applyTemperature: logits에 온도 적용 후 softmax
func applyTemperature(logits []float64, temp float64) []float64 {
	if temp <= 0 {
		temp = 1.0
	}
	scaled := make([]float64, len(logits))
	for i, v := range logits {
		scaled[i] = v / temp
	}
	return softmax1D(scaled)
}

// topKSample: 상위 K개 후보에서 확률적 샘플링
func topKSample(probs []float64, k int) int {
	type tv struct{ idx int; p float64 }
	cands := make([]tv, len(probs))
	for i, p := range probs {
		cands[i] = tv{i, p}
	}
	sort.Slice(cands, func(i, j int) bool { return cands[i].p > cands[j].p })
	if k > len(cands) {
		k = len(cands)
	}
	cands = cands[:k]

	// 재정규화
	sum := 0.0
	for _, c := range cands { sum += c.p }
	r := rand.Float64() * sum
	cum := 0.0
	for _, c := range cands {
		cum += c.p
		if r <= cum {
			return c.idx
		}
	}
	return cands[0].idx
}

// nucleusSample: top-p (nucleus) 샘플링
func nucleusSample(probs []float64, p float64) int {
	type tv struct{ idx int; prob float64 }
	cands := make([]tv, len(probs))
	for i, prob := range probs {
		cands[i] = tv{i, prob}
	}
	sort.Slice(cands, func(i, j int) bool { return cands[i].prob > cands[j].prob })

	// 누적 확률이 p를 넘는 최소 집합
	cum := 0.0
	cut := len(cands)
	for i, c := range cands {
		cum += c.prob
		if cum >= p {
			cut = i + 1
			break
		}
	}
	nucleus := cands[:cut]

	sum := 0.0
	for _, c := range nucleus { sum += c.prob }
	r := rand.Float64() * sum
	acc := 0.0
	for _, c := range nucleus {
		acc += c.prob
		if r <= acc {
			return c.idx
		}
	}
	return nucleus[0].idx
}

// greedySample: argmax
func greedySample(probs []float64) int {
	best, bestP := 0, probs[0]
	for i, p := range probs {
		if p > bestP {
			best, bestP = i, p
		}
	}
	return best
}

// ─────────────────────────────────────────────────
// BPModel.Generate — 핵심 생성 루프
// ─────────────────────────────────────────────────

type SamplingConfig struct {
	Method      string  // "greedy" | "topk" | "nucleus"
	Temperature float64 // 0.1 ~ 2.0
	TopK        int     // top-k k 값
	TopP        float64 // nucleus p 값 (0 ~ 1)
	MaxTokens   int
}

func DefaultConfig() SamplingConfig {
	return SamplingConfig{
		Method:      "nucleus",
		Temperature: 0.8,
		TopK:        40,
		TopP:        0.9,
		MaxTokens:   200,
	}
}

// Generate: 프롬프트 토큰 리스트 → 생성된 토큰 리스트
func (m *BPModel) Generate(prompt []int, cfg SamplingConfig) []int {
	ctx := make([]int, len(prompt))
	copy(ctx, prompt)

	generated := []int{}
	maxCtx := 128 // 최대 컨텍스트 길이

	for i := 0; i < cfg.MaxTokens; i++ {
		// 컨텍스트 윈도우 제한
		input := ctx
		if len(input) > maxCtx {
			input = input[len(input)-maxCtx:]
		}

		logits, _ := m.forwardBP(input)
		probs := applyTemperature(logits, cfg.Temperature)

		var next int
		switch cfg.Method {
		case "greedy":
			next = greedySample(probs)
		case "topk":
			next = topKSample(probs, cfg.TopK)
		default: // nucleus
			next = nucleusSample(probs, cfg.TopP)
		}

		ctx = append(ctx, next)
		generated = append(generated, next)
	}
	return generated
}

// ─────────────────────────────────────────────────
// 토큰 → 문자열 변환
// ─────────────────────────────────────────────────

func tokensToString(tokens []int, vocab map[string]int) string {
	// 역방향 vocab
	rev := make(map[int]string, len(vocab))
	for ch, id := range vocab {
		rev[id] = ch
	}
	var sb strings.Builder
	for _, t := range tokens {
		if ch, ok := rev[t]; ok {
			sb.WriteString(ch)
		} else {
			sb.WriteString("?")
		}
	}
	return sb.String()
}

func stringToTokens(s string, vocab map[string]int) []int {
	tokens := []int{}
	for _, ch := range s {
		if id, ok := vocab[string(ch)]; ok {
			tokens = append(tokens, id)
		} else {
			tokens = append(tokens, 0) // <UNK>
		}
	}
	return tokens
}

// ─────────────────────────────────────────────────
// generateBP: 학습 후 즉시 호출되는 데모
// ─────────────────────────────────────────────────

func generateBP(model *BPModel, vocab map[string]int) {
	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("🔤 Mission 1: Text Generation (Inference)")
