	}{
		{SamplingConfig{"greedy",  1.0, 0,  0,   80}, "Greedy"},
		{SamplingConfig{"topk",    0.8, 20, 0,   80}, "Top-K(k=20, t=0.8)"},
		{SamplingConfig{"nucleus", 0.8, 0,  0.9, 80}, "Nucleus(p=0.9, t=0.8)"},
		{SamplingConfig{"nucleus", 1.2, 0,  0.95, 80}, "Nucleus(p=0.95, t=1.2) creative"},
	}

	for _, pr := range prompts {
		promptToks := stringToTokens(pr.text, vocab)
		if len(promptToks) == 0 {
			continue
		}

		fmt.Printf("┌─ 프롬프트: %q (%s)\n", pr.text, pr.desc)
		for _, c := range configs {
			gen := model.Generate(promptToks, c.cfg)
			full := tokensToString(append(promptToks, gen...), vocab)
			// 출력 정리: 제어문자 제거, 100자 제한
			clean := cleanOutput(full, 100)
			fmt.Printf("│  [%-32s] %s\n", c.name, clean)
		}
		fmt.Println("└──────────────────────────────────────────────────────────")
		fmt.Println()
	}

	// Top-1 확률 분포 분석
	fmt.Println("📊 다음 토큰 확률 분포 (프롬프트: \"fn \"):")
	sample := stringToTokens("fn ", vocab)
