func trainBP() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 7: Full Backpropagation Transformer (정확한 역전파)  ║")
	fmt.Println("║  수정: LN/Attn/Emb backward 근사 완전 제거                ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	fmt.Println("[1/5] Loading data (corpus.txt 200K chars)...")
	tokens, vocab, err := loadCorpus("data/corpus.txt", 200_000, 300)
	if err != nil {
		fmt.Printf("❌ corpus.txt: %v\n", err)
		fmt.Println("⚠️  fallback → real_corpus_large.txt")
		tokens, vocab, err = tokenizeRealData("data/real_corpus_large.txt")
		if err != nil {
			fmt.Printf("❌ %v\n", err)
			return
		}
	}
	fmt.Printf("✅ tokens=%d, vocab=%d\n\n", len(tokens), len(vocab))

	d        := 128
	ffn      := 512
	numHeads := 4

	fmt.Println("[2/5] Creating BP Transformer...")
	model := newBPModel(len(vocab), d, ffn, numHeads)
	paramCount := len(vocab)*d + d*d*4 + d*ffn*2 + d*len(vocab)
	fmt.Printf("✅ d=%d, heads=%d, FFN=%d, params=~%dk\n\n", d, numHeads, ffn, paramCount/1000)

	fmt.Println("[3/5] Initializing Adam (14 instances)...")
	adam := newBPAdams(0.0003, len(vocab), d, ffn)
	fmt.Printf("✅ Adam ready (lr=0.0003, β1=0.9, β2=0.999)\n\n")

	seqLen      := 64
	epochs      := 10
	numBatches  := 400
	warmupSteps := 400
	totalSteps  := epochs * numBatches

	fmt.Println("[4/5] Training config:")
	fmt.Printf("   seqLen=%d, epochs=%d, batches/epoch=%d\n", seqLen, epochs, numBatches)
	fmt.Printf("   warmup=%d steps, cosine decay\n", warmupSteps)
	fmt.Printf("   데이터: corpus.txt 200K chars, vocab=%d\n\n", len(vocab))

	fmt.Println("[5/5] Training...")
	fmt.Println("══════════════════════════════════════════════════════════════")

	losses  := make([]float64, 0, epochs)
	bestPPL := math.MaxFloat64

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < numBatches; batch++ {
			startIdx := rand.Intn(len(tokens) - seqLen - 1)
			seq       := tokens[startIdx : startIdx+seqLen]
			targetTok := tokens[startIdx+seqLen]

			logits, cache := model.forwardBP(seq)
			probs := softmax1D(logits)

			loss := math.Log(float64(len(vocab))) // fallback
			if targetTok < len(probs) && probs[targetTok] > 1e-10 {
				loss = -math.Log(probs[targetTok])
			}
			epochLoss += loss

			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if targetTok < len(dLogits) { dLogits[targetTok] -= 1.0 }

			// LR schedule: warmup + cosine
			step := (epoch-1)*numBatches + batch + 1
			var lr float64
			if step < warmupSteps {
				lr = 0.0003 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0003 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adam.setLR(lr)

			model.backwardStep(seq, targetTok, cache, dLogits, adam)

			if batch%100 == 0 {
				avg := epochLoss / float64(batch+1)
				fmt.Printf("Epoch %02d/%d  batch %3d/%d  loss=%.4f  ppl=%.1f  lr=%.5f\r",
					epoch, epochs, batch+1, numBatches, avg, math.Exp(avg), lr)
			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses  = append(losses, avgLoss)
		ppl     := math.Exp(avgLoss)
		marker  := ""
		if ppl < bestPPL {
			bestPPL = ppl
			marker  = " ★ best"
		}
		fmt.Printf("\n✅ Epoch %02d: loss=%.4f  PPL=%.2f%s\n", epoch, avgLoss, ppl, marker)
	}

	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("📊 학습 곡선:")
	for i, l := range losses {
		bar := ""
		if len(losses) > 1 && losses[0] > l {
			n := int((losses[0]-l)/losses[0]*40)
			for j := 0; j < n; j++ { bar += "█" }
		}
		fmt.Printf("  Epoch %02d: %s %.4f (PPL: %.2f)\n", i+1, bar, l, math.Exp(l))
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp  := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Phase 7 결과:\n")
		fmt.Printf("   Initial PPL: %.2f\n", iPPL)
		fmt.Printf("   Final PPL:   %.2f\n", fPPL)
		fmt.Printf("   Best PPL:    %.2f ★\n", bestPPL)
		if imp > 0 {
			fmt.Printf("   개선:        %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   악화:        %.1f%% ⚠️\n\n", -imp)
		}
	}
}

